import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBC: [CaseTemplate] = [trawlerCatchShare, hospitalStairwellBeating, dialysisStaffThreat, restStopWrench, quarryHopperShove, ferryPilotBreath, deerCarcassFight, volunteerFireSetter, tentRevivalCures, aideWillChange, catfishSingerGiftCards, payrollTaxSkim, hospiceMorphineSwap, courierDriveUpRobbery, carWashToyGun, laundromatClosingRobbery, bakeryDawnRobbery, armoredRoutePlot, trophyShotguns, funeralHomeJewelry, bandRoomBurglary, churchOfficeSafe, vanWithSleepingChild, kayakLoadTheft, busConverterRing, truckStopRigTheft, calfBarnTheft, lumberLoadTheft, beeHiveTheft, hardwareGreenhouseGrow, poolHallScales, fentanylPatchStash, boatRampCooler, bathSaltsPorch, twoOverdoseDealer, alteredScripts, fakeGameWarden, blueLightsRoadStops]

    static let trawlerCatchShare = SmallCases.make(
        key: "story.trawlerCatchShare",
        category: .violent,
        headlines: ["Deckhand Stabbed by Shipmate on Shrimp Trawler Over Catch Shares", "Boat Returns to Dock With Blood on Deck"],
        law: "awdwikisi",
        threshold: 8,
        spec: "Assaulted {V} with a knife inflicting serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a deckhand, was stabbed in the shoulder on a shrimp trawler on {DATE} after an argument over catch shares. {D}, the first mate, was holding a knife when the boat docked. {DL} says {V} came at {D.him} with a hook.",
        state: [E(.statement, 3, "Captain", "'I saw {D} with the knife over {V}.'"), E(.physical, 3, "Knife", "A fillet knife with blood in the galley.", .search), E(.forensic, 2, "Medical Report", "A four-inch shoulder wound.")],
        defense: [E(.statement, 1, "Hook", "{DL} says {V} came with a gaff hook.")],
        role: "Trawler captain",
        exam: [.direct("What did you see on the trawler that day?", "\"I saw {D}, my first mate, standing over {V} with a knife in hand in the galley. {V} had been stabbed in the shoulder.\""), .direct("What had the argument been about?", "\"Catch shares. The crew splits the catch by shares, and {D} had threatened to dock {V}'s share before it blew up.\""), .direct("What did you find when the boat docked?", "\"A fillet knife with blood on it in the galley, and {V} with a four-inch shoulder wound that needed treatment.\""), .direct("How long had this crew worked together, and how were shares set?", "\"Most of the season, five of us. Shares come off the dock price, and the first mate figures them. A deckhand gets a share by hours and rank, and everyone knows the formula.\""), .direct("What did you do when you heard the commotion?", "\"I came down from the wheelhouse at about 5:10 in the morning. I found {D} standing over {V} in the galley with a fillet knife while {V} held {V.his} shoulder.\""), .direct("What did you do for {V} until the dock?", "\"I wrapped the shoulder in a clean towel, kept pressure on it, and radioed ahead for an ambulance. We reached the dock around 7 a.m. and medics took over.\""), .cross("{D} says {V} came at {D.him} with a hook, doesn't {D.he}?", "\"I know that is what {D} says. A gaff hook did lie near {V}'s hand when I got there.\""), .cross("Did you see {V} swing the hook?", "\"No. I came in after it started. I saw {D} with the knife and {V} on the deck, nothing before that.\""), .cross("Is a fillet knife a normal tool on a trawler?", "\"Yes. Every galley has them for cutting line and fish. It is a work tool, and it was where it belonged.\""), .cross("You were in the wheelhouse and saw only the end of the fight, correct?", "\"Correct. I did not see how it started or who moved first, only the knife and {V} bleeding on the deck.\""), .cross("Did you see the gaff hook in {V}'s hand?", "\"It lay on the deck near {V}'s hand. I could not tell whether {V} had been holding it when the knife came out.\"")],
        defenseRole: "Second deckhand",
        defenseExam: [.direct("What did you see from your position at the stern?", "\"I saw {V} raise a gaff hook toward {D} during the argument. It was quick, and I was not close.\""), .direct("How far were you from the two of them?", "\"About thirty feet toward the stern. I could see both of them clearly, though not every detail of what they said.\""), .direct("What did {D} do right after {V} raised the hook?", "\"{D} grabbed a knife and struck out once. It happened in a second, and then both of them were still.\""), .direct("What do you do on the trawler?", "\"I am the second deckhand. I sort the catch, mend the nets, and help rinse the deck. I was by the stern door of the galley that morning.\""), .direct("What had the mood been like that week?", "\"Tense. {V} was complaining about the share every day, and {D} told {V} the cut was final. It built up quickly.\""), .direct("What did you see as the argument grew?", "\"{V} went to the rack, picked up a gaff hook, and started toward {D}. {D} grabbed the knife from the counter. It was over in seconds.\""), .cross("Why had {V} been so angry?", "\"I think it was about the share. {D} had said {V}'s share would be docked.\""), .cross("Did you hear what was said before?", "\"Only shouting. I could not make out the words from where I stood.\""), .cross("Did you see {V} swing the hook?", "\"No. I saw it lifted, then I saw {D}'s arm move. After that, {V} was on the deck.\""), .cross("Why didn't you step in?", "\"It happened too fast. I was thirty feet away and I froze. I regret that I did not do something sooner.\""), .cross("You were a few steps away, so you could not see everything, could you?", "\"Not every moment. I saw the hook rise and the first swing, and then the two were tangled together at the rail.\"")],
        theory: ("{D} stabbed a deckhand.", "A defense."),
        allocution: "\"I never meant to cut {V.him} that deep.\"",
        truths: ("{DL} had threatened to dock {V}'s share.", "A gaff hook lay by {V}'s hand."),
        defendant: [.direct("Did you stab {V}?", "\"Yes, I did. {V} swung a gaff hook at me, and I grabbed the knife and struck out in fear.\""), .direct("Why did you have a knife in the galley?", "\"I was cutting line when the argument started. It was in my hand because I had been working.\""), .direct("Who decided to dock {V}'s share?", "\"I did. As first mate, I set the shares, and I told {V} the share would be cut. That is why we argued.\""), .direct("How long have you been first mate on this boat?", "\"Six seasons. I handle the books, set shares, and stand watch with the captain. It is not an easy job, and people get angry over money.\""), .direct("What happened in the galley at about 5 a.m.?", "\"{V} came in swearing about a short share. I told {V} the number was final. {V} grabbed a gaff hook from the rack and came at me.\""), .direct("What did you do after you struck {V}?", "\"I dropped the knife and tried to stop the bleeding. The captain came in, and I stayed until we docked. I told the deputies what I had done.\""), .cross("Why did you not call for help right away?", "\"I panicked. I stood there with the knife, and I did not know what to do. I should have called.\""), .cross("You threatened to dock {V}'s share before the fight, didn't you?", "\"Yes. I did. It was a business decision, and I did not plan to hurt anyone over it.\""), .cross("A four-inch wound in the shoulder is serious. Was that necessary?", "\"I was afraid. I struck once. I did not aim, and I am sorry it went that deep.\""), .cross("You are the one who decided to dock {V}'s share. Isn't that what started this?", "\"It was my decision as first mate, and it upset {V}. I would do it more carefully now, but it did not justify violence.\""), .cross("You could have stepped out of the galley. Why didn't you?", "\"It is a cramped space and {V} was between me and the door. I did not have an easy way out.\"")],
        openings: ("On a shrimp trawler, {V}, a deckhand, was stabbed in the shoulder after an argument over catch shares. When the boat docked, the captain saw {D}, the first mate, holding a bloody knife over {V}.", "Weigh the defense proof, which will show that {V} raised a gaff hook at {D}, that a second deckhand saw it, and that {D} struck out once in fear."),
        closings: ("An argument over shares, a threat to dock them, a bloody knife in the galley, and a four-inch wound. The captain saw {D} standing over {V}.", "A gaff hook raised in a cramped galley, and a first mate who struck once in fear. A second deckhand saw the hook, and {D} acted to protect {D.himself}."),
        timeline: [(-1, "The catch share dispute."), (0, "5 a.m.: the argument."), (0, "5:10 a.m.: the stabbing."), (0, "7 a.m.: the boat docks.")],
        identified: "A captain and a knife.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I can't haul nets now.",
        doctrines: ["selfDefense"],
        genders: ["D": .male, "V": .male])

    static let hospitalStairwellBeating = SmallCases.make(
        key: "story.hospitalStairwellBeating",
        category: .violent,
        headlines: ["Security Guard Beats Patient in Hospital Stairwell", "Cameras Cover Stairwell Entrance"],
        law: "assaultFemale",
        threshold: 8,
        spec: "Assaulted {V}, a female, being a male person at least 18 years of age, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a patient, was found beaten in a hospital stairwell on {DATE}. {D}, a security guard, was the last to enter. {DL} says {V} fell down the stairs.",
        state: [E(.video, 3, "Stairwell Camera", "{D} enters; {V} later carried out."), E(.forensic, 3, "Medical Report", "Bruises inconsistent with a fall."), E(.statement, 2, "Nurse", "'{V} said {D} hit {V.him}.'")],
        defense: [E(.statement, 1, "Fall", "{DL} says {V} fell.")],
        role: "Charge nurse",
        exam: [.direct("What did you find at the hospital on {DATE}?", "\"{V}, a patient, was found beaten in a stairwell. {V} was carried out and brought to us, and I was the charge nurse who treated {V.him}.\""), .direct("What did {V} tell you?", "\"{V} said {D}, a security guard, hit {V.him}. {V} said it clearly, and I wrote it down in my notes.\""), .direct("What does the stairwell camera show?", "\"{D} enters the stairwell, and {V} is later carried out. {D} was the last person to enter before {V} was found.\""), .direct("What did you see when {V} was brought to you?", "\"{V} was carried into the unit around 1:25 a.m. with bruises on the face and ribs and a split lip. {V} was frightened and kept looking over my shoulder.\""), .direct("What did {V} say to you, and how did {V} say it?", "\"Quietly but clearly: 'The guard hit me.' I wrote it in the chart in {V}'s words and told the doctor. {V} repeated it to me later.\""), .direct("What did the medical team find?", "\"Bruises across the cheek and upper arm, with a pattern that looked more like blows than a fall. The doctor documented it in the report.\""), .cross("{DL} says {V} fell, doesn't {D.he}?", "\"But the medical report shows bruises inconsistent with a fall. I'm not a pathologist, but I treated the injuries.\""), .cross("Was {V} confused?", "\"{V} was in pain and shaken. {V} was a patient, but {V} told me the same thing more than once.\""), .cross("Did you see the stairwell before the camera footage?", "\"I saw it afterward. I didn't see the incident. I can tell you what I saw on {V}'s body.\""), .cross("Did {V} have any medication or condition that affects memory?", "\"{V} was on pain medication from a prior procedure. It could cause drowsiness, but {V} was oriented to the date and place.\""), .cross("Did you see anything in the stairwell yourself?", "\"No. I was on the floor when it happened. I only saw {V}'s injuries afterward.\"")],
        defenseRole: "Maintenance worker",
        defenseExam: [.direct("Do you maintain the hospital's stairwells?", "\"Yes. I'm a maintenance worker. I check railings and stairs when staff reports a problem.\""), .direct("Was the railing in that stairwell loose?", "\"Yes. It was loose in the lower flight. I noticed it when I did my rounds.\""), .direct("Did you report it?", "\"Yes. I put it in a work order the week before. It hadn't been fixed yet.\""), .direct("How long have you worked at the hospital?", "\"Nine years. I handle repairs, replace lights, and fix doors and railings on every floor.\""), .direct("What was wrong with that stairwell?", "\"The handrail on the lower flight had a loose bracket, and a few of the steps had worn nosing. It was on my list, but I had not gotten to it.\""), .direct("How do you know it was loose?", "\"I had grabbed it myself a few days before and felt it move. I wrote a work order and passed it up.\""), .cross("Was the railing the cause of a fall?", "\"I can't say. I wasn't there. I only know it was loose.\""), .cross("Did you see {V} fall?", "\"No. I wasn't in the stairwell. I only know the condition of the stairs.\""), .cross("Could a loose railing cause bruising like that?", "\"I'm not a doctor. A loose railing can cause a fall, but I can't say about bruises.\""), .cross("Did anyone fall on that stair before this?", "\"Not that I recall. A few people complained about the rail.\""), .cross("Do you know what happened to {V} that night?", "\"No. I was off shift. I only know the condition of the stairs.\"")],
        theory: ("{D} beat a patient.", "A fall."),
        allocution: "\"I'm so sorry.\"",
        truths: ("{DL} had two prior complaints from patients.", "The stairwell railing was loose."),
        defendant: [.direct("Why did you go into the stairwell?", "\"I was making my rounds. I heard a noise and went in. I found {V} on the stairs and I called for help.\""), .direct("Did you strike {V}?", "\"No. I never touched {V.him}. I found {V.him} hurt on the stairs. I'd never hit a patient.\""), .direct("What do you think happened?", "\"{V} fell. The stairwell is not in great shape. I think {V} lost footing and fell down the stairs.\""), .direct("How long have you been a hospital guard?", "\"Four years. I walk the floors on the overnight and answer calls from staff. Stairwell checks are part of my route.\""), .direct("What did you see when you entered at 1:10?", "\"{V} was sitting on the landing, bleeding from the mouth, and gasping. I thought {V} had fallen and called for help right away.\""), .direct("What did you do next?", "\"I radioed for a nurse and stayed with {V} until staff arrived. I did not leave, and I told the nurse what I saw.\""), .cross("You were the last person to enter, weren't you?", "\"Yes. I went in after others had gone. I found {V}. That doesn't mean I caused it.\""), .cross("The medical report says the bruises are inconsistent with a fall, doesn't it?", "\"That's what they say. I'm not a doctor. I only know I didn't hit {V.him}.\""), .cross("{V} says you hit {V.him}, doesn't {V.he}?", "\"That's what {V} says. I don't know why. I'm sorry {V} believes that.\""), .cross("The camera shows you going in after {V} walked out. Do you see why that looks bad?", "\"I do. But I went in to check, found {V} hurt, and called it in. Someone who had hurt {V} would not do that.\""), .cross("The report says the bruises do not fit a fall. Are you calling the doctor wrong?", "\"I am not calling anyone wrong. I know only that I did not hit {V}.\"")],
        openings: ("A patient was found beaten in a hospital stairwell, and told a nurse that {D}, a security guard, hit {V.him}. The stairwell camera shows {D} entering as the last person before {V} was carried out. The State will show the camera and the medical report.", "The defense will present a stairwell with a loose railing, a fall that could explain injuries, and a guard who found {V} and called for help."),
        closings: ("A patient beaten, bruises that don't fit a fall, and {D} the last one to enter the stairwell. {V} named {D} to the nurse at once.", "A loose railing and a steep stairwell make a fall plausible. The State has not proved {D} struck {V}, and a guard who calls for help is not an attacker."),
        timeline: [(0, "1 a.m.: {V} walks out."), (0, "1:10 a.m.: {D} follows."), (0, "1:25 a.m.: {V} is found."), (0, "2 a.m.: {V} is treated.")],
        identified: "A hospital camera.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I was afraid to go back.",
        doctrines: ["burdenOfProof"])

    static let dialysisStaffThreat = SmallCases.make(
        key: "story.dialysisStaffThreat",
        category: .violent,
        headlines: ["Patient Threatens to Shoot Staff at Dialysis Center", "Note Found in Waiting Room"],
        law: "massViolenceThreat",
        threshold: 7,
        spec: "Threatened to commit mass violence at a medical facility, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A note on {DATE} said staff at a dialysis center would be shot Friday. Handwriting matched {D}, a patient angry about billing. {DL} says it was a joke.",
        state: [E(.document, 3, "Note", "'You'll all be shot Friday.'"), E(.forensic, 3, "Handwriting Report", "Matches {D}."), E(.video, 2, "Waiting Room Camera", "{D} leaves a folded paper.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke.")],
        role: "Clinic director",
        exam: [.direct("What did you find on {DATE}?", "\"A note that read, 'You'll all be shot Friday.' It was left at our dialysis center, and staff were frightened.\""), .direct("How did you tie the note to {DL}?", "\"A handwriting report matched {D}. And the waiting room camera shows {D} leaving a folded paper.\""), .direct("Why would {DL} have a grievance?", "\"{D} is a patient angry about billing. There had been a dispute over charges.\""), .direct("How was the note discovered?", "\"A technician found a folded paper on the waiting room table at 9 a.m. It read, 'You'll all be shot Friday,' and the handwriting was in block capitals.\""), .direct("What did you do after reading it?", "\"I called deputies, closed the center at 9:30, and moved patients to other facilities. Treatments were interrupted for dozens of people that day.\""), .direct("How did you identify {D}?", "\"The camera showed {D} placing a folded paper on the table and walking out. A handwriting examiner later matched the note to {D}'s signed forms.\""), .cross("{DL} says it was a joke, doesn't {D.he}?", "\"I can't tell if it was a joke. I can tell you how staff reacted to it.\""), .cross("Was anyone hurt?", "\"No. No one was hurt. We called deputies and put safety steps in place.\""), .cross("Did {DL} threaten anyone directly?", "\"Not in person. It was a note. {D} did not say anything to staff that I know of.\""), .cross("Did {D} ever make threats at the clinic before?", "\"No. There had been arguments about the bill, but no threats before this note.\""), .cross("Was {D} still receiving treatment?", "\"Yes. {D} came three times a week and was a regular. Several staff liked {D}.\"")],
        defenseRole: "Billing clerk",
        defenseExam: [.direct("Do you work in the billing office?", "\"Yes. I deal with patient accounts. I know {D}'s billing situation well.\""), .direct("How did {DL} react to the billing issue?", "\"Upset, but not violent. {D} joked about it with me afterward. {D} laughed it off.\""), .direct("Did {DL} say anything about the note?", "\"{D} laughed about it. {D} didn't treat it like a plan. It sounded like a joke.\""), .direct("How long have you worked in billing?", "\"Seven years. I handle statements, insurance calls, and patient complaints about balances.\""), .direct("How did {D}'s billing problem come about?", "\"An insurer denied a claim by mistake, and {D}'s account showed a balance. We were trying to fix it, but it took weeks.\""), .direct("How did {D} act when you spoke?", "\"Frustrated, but polite. {D} told me the billing system was a mess and made a dark joke about it.\""), .cross("Did {DL} joke to staff about shooting?", "\"Not to me. I don't know what {D} said to others.\""), .cross("Were you at the center when the note was left?", "\"No. I was in the billing office. I only heard afterward.\""), .cross("Is shooting a funny topic to you?", "\"No. I don't think it's funny. I'm only telling what I saw of {D}.\""), .cross("Did you hear the joke about shooting?", "\"No. I heard about the note after it was found. I did not hear {D} make any such joke.\""), .cross("Did {D} ever show any interest in weapons?", "\"I have no knowledge of that. We only spoke about billing.\"")],
        theory: ("{D} threatened a clinic.", "A joke."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} owned a rifle.", "{DL} told the receptionist the note was a bad joke within the hour."),
        defendant: [.direct("Did you write the note?", "\"Yes. I wrote it as a joke. I was angry about my bill, and I thought it was funny. I didn't mean it.\""), .direct("Why did you leave it in the waiting room?", "\"I left it for the staff to find. I wanted them to see I was frustrated. I never meant to scare anyone.\""), .direct("Do you intend to harm anyone?", "\"No. I'd never hurt anyone at the clinic. They keep me alive. I'm ashamed of the note.\""), .direct("Why had the billing dispute upset you so much?", "\"I received a bill for a large amount that my insurance should have covered. I called several times and kept getting transferred.\""), .direct("What did you mean by writing that note?", "\"It was a stupid joke. I wanted staff to take my complaint seriously, and I thought they would laugh. I did not think about how it would land.\""), .direct("What did you do when you realized staff were upset?", "\"I told the receptionist within the hour that it was a bad joke. I said I was sorry and that I did not mean harm to anyone.\""), .cross("'You'll all be shot Friday' isn't funny, is it?", "\"No. I see that now. At the time I wasn't thinking.\""), .cross("You were angry about the billing, weren't you?", "\"Yes. I felt ignored. I've never been violent, but I let my anger out the wrong way.\""), .cross("Staff were frightened, weren't they?", "\"I understand they were. I'm very sorry.\""), .cross("A threat of shooting staff on a particular day is not a joke for a medical clinic. Don't you agree?", "\"I agree now. I was angry and not thinking clearly. I am embarrassed and ashamed.\""), .cross("Why Friday?", "\"It was just a day. I picked it because it was the end of the week, and I did not think of it as a real date.\"")],
        openings: ("A note at a dialysis center said, 'You'll all be shot Friday.' A handwriting report matches {D}, a patient angry about billing, and the waiting room camera shows {D} leaving a folded paper. The State will show the note and the report.", "Jurors will also see a patient who wrote a bad joke out of frustration over a bill, who laughed about it, and who has never harmed anyone."),
        closings: ("A note promising staff would be shot, handwriting that matches {D}, and a camera showing {D} leaving it. Staff feared for their lives because of it.", "A foolish joke about a bill, written by a patient who depends on that clinic. The State has not proved {D} meant it as a real threat."),
        timeline: [(-14, "A billing dispute."), (0, "9 a.m.: the note."), (0, "9:30 a.m.: the clinic closes."), (1, "{DL} is arrested.")],
        identified: "Handwriting.",
        aggravating: ["The offense involved a threat"],
        mood: .divided,
        impact: "We were afraid to open.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let restStopWrench = SmallCases.make(
        key: "story.restStopWrench",
        category: .violent,
        headlines: ["Trucker Hit With Wrench at Rest Area Over Parking Spot", "Dash Camera Catches Argument"],
        law: "awdwik",
        threshold: 8,
        spec: "Assaulted {V} with a wrench with intent to kill, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a long-haul driver, was struck in the head with a wrench at a rest area on {DATE} after a parking dispute. {D} was found with a wrench in his cab. {DL} says {V} threatened {D.him} first.",
        state: [E(.forensic, 3, "Medical Report", "Skull fracture."), E(.physical, 3, "Wrench", "A wrench with blood in {D}'s cab.", .search), E(.video, 2, "Dash Camera", "Two drivers argue.")],
        defense: [E(.statement, 1, "Threat", "{DL} says {V} threatened {D.him}.")],
        role: "Rest area attendant",
        exam: [.direct("What did you see at the rest area?", "\"Two drivers were arguing over a parking space. Then one of them was on the ground, bleeding from the head.\""), .direct("What did the dash camera show?", "\"Two drivers arguing. It does not show the blow, but it shows the argument getting loud.\""), .direct("What did deputies find in {D}'s cab?", "\"A wrench with blood on it. {V} had a skull fracture, according to the medical report.\""), .direct("How was the rest area laid out that night?", "\"A truck lot with two rows of parking, lit by tall lamps at the ends. Drivers park for rest breaks, and the busy hours are overnight.\""), .direct("What did you hear and see around 2 a.m.?", "\"Two drivers were shouting beside their cabs about who had taken a space. I stayed in my booth until the shouting stopped, and then I heard a loud thud.\""), .direct("What did you do after the thud?", "\"I ran over and saw {V} on the pavement with blood on the head. I called 911 at 2:15 and applied a towel until the medics came.\""), .cross("Did you see who hit {V}?", "\"No. I heard the shouting and came out. I did not see the blow itself.\""), .cross("Did {V} reach for anything?", "\"I heard that {V} reached into a toolbox.\""), .cross("How long was the argument?", "\"A few minutes. It got heated, but I did not see a fight until it was over.\""), .cross("Did you see anyone hit {V}?", "\"No. I only saw {V} on the ground and {D} standing nearby. I could not tell you what happened in between.\""), .cross("Did {D} try to leave?", "\"No. {D} stayed by the cab and told me to call for help. {D} did not run.\"")],
        defenseRole: "Fellow driver",
        defenseExam: [.direct("What did you see at the rest area?", "\"I saw {V} lift something dark toward {D} during the argument. It looked like a tool or a bar.\""), .direct("How far were you from the two drivers?", "\"About twenty yards, parked near the pumps. I had a clear line of sight between the trucks.\""), .direct("What did {D} do after {V} lifted it?", "\"{D} swung something at {V}. It all happened in seconds, and then {V} was down.\""), .direct("How do you know about trucking?", "\"I drive long haul too. I was parked near the pumps when I saw the argument start.\""), .direct("What did you notice about {V}?", "\"{V} was shouting and waving an arm. Then {V} turned and reached toward the toolbox on the side of the truck.\""), .direct("What happened when {V} reached?", "\"{D} swung a tool, and {V} dropped. It all took about three seconds.\""), .cross("Could you tell what {V} was holding?", "\"No. It was dark, and I could not see it clearly. I only saw something raised.\""), .cross("Did you see {V} swing at {D}?", "\"No. I saw it raised. I did not see a swing.\""), .cross("Do you know {D} from before?", "\"We have met on the road. I do not know much about {D}, and I am telling you only what I saw.\""), .cross("Did you hear what {V} said?", "\"Only that {V} was loud. I could not make out the words from twenty yards.\""), .cross("Why didn't you step in?", "\"It happened so fast I did not have time. I called out, but it was already over.\"")],
        theory: ("{D} struck a trucker.", "A threat."),
        allocution: "\"I lost my head.\"",
        truths: ("{DL} had a prior road rage complaint.", "{V} reached into a toolbox."),
