        spec: "Unlawfully killed {V} without malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a quarry worker, died on {DATE} after falling into a crusher hopper where a safety rail had been removed. {D}, the foreman, was seen shoving {V.him}. {DL} says {V} slipped.",
        state: [E(.statement, 3, "Coworker", "'{D} shoved {V}.'"), E(.forensic, 3, "Autopsy", "Fatal crush injuries."), E(.document, 2, "Safety Report", "The rail was removed that morning.")],
        defense: [E(.statement, 1, "Slip", "{DL} says {V} slipped.")],
        role: "Quarry coworker",
        exam: [.direct("What did you see at the crusher hopper?", "\"I saw {D}, the foreman, shove {V}, and {V} fell into the crusher hopper. {V} died from the crush injuries.\""), .direct("What was different about the hopper that morning?", "\"The safety rail had been removed that morning. The safety report confirms it, and there were no warning signs.\""), .direct("What did you tell investigators?", "\"That I saw {D} push {V} just before the fall. The autopsy confirms fatal crush injuries.\""), .direct("What was your job at the quarry that morning?", "\"I ran a loader near the crusher. I was a few dozen feet away loading trucks when the argument started on the catwalk near the hopper.\""), .direct("What did you see {D} do?", "\"{D} and {V} were face to face near the edge, and {D} put both hands on {V}'s chest and pushed. {V} backpedaled and fell over the edge.\""), .direct("What happened next?", "\"I shouted, hit the emergency stop, and ran toward the hopper. {V} was already caught in the crusher, and I could do nothing but call for help.\""), .cross("Could {V} have slipped on wet ground?", "\"The ground was wet that morning. I know that, and I do not rule it out.\""), .cross("Did {D} reach toward {V}?", "\"It looked like {D} reached for {V}. I will not say it was not a reach.\""), .cross("How far were you from the hopper?", "\"About forty feet. I had a clear view, but it was fast.\""), .cross("Could {V} have stepped back and lost balance on the wet gravel?", "\"It was wet, and I know that. But I saw {D}'s hands go out to {V}'s chest. I am sure of that part.\""), .cross("How loud was the equipment?", "\"Very loud. I could not hear the argument, only see it. It was the position of the hands I noticed.\"")],
        defenseRole: "Safety inspector",
        defenseExam: [.direct("Why was the rail off the hopper?", "\"It was removed for repair work that morning. Maintenance had it off, and it was meant to go back on.\""), .direct("Were there warning signs?", "\"None that I saw. The area should have been marked off while the rail was down.\""), .direct("Whose job was it to post warnings?", "\"The foreman or the crew doing the maintenance. It was part of the procedure.\""), .direct("How long have you inspected quarries?", "\"Nineteen years. I check guardrails, lockouts, and signage, and I write citations when something is not right.\""), .direct("What did you find at the hopper after the incident?", "\"The guardrail was off, and there was no warning tape or barrier. The ground around it was wet from rain.\""), .direct("What do the rules require when a rail is removed?", "\"A barrier, a sign, and a lockout on the crusher. None of those were in place.\""), .cross("Who ordered the rail removed?", "\"I think {D}, as foreman. I did not see the order, but that is the chain of command.\""), .cross("Was the ground wet around the hopper?", "\"Yes. It had rained, and the footing was slick near the edge.\""), .cross("Do you know what happened when {V} fell?", "\"No. I arrived afterward. I only know the scene I found.\""), .cross("Did you see {V} fall?", "\"No. I arrived after the fact and reconstructed the scene from reports.\""), .cross("Who is responsible for those safety steps?", "\"The foreman and the maintenance crew share it. It was {D}'s area that morning.\"")],
        theory: ("{D} shoved a worker to his death.", "A slip."),
