        openings: ("{V}, a quarry worker, died after falling into a crusher hopper from which a safety rail had been removed that morning. A coworker saw {D}, the foreman, shove {V}.", "The defense will present evidence that the ground was wet, that {V} slipped, and that {D} reached out to catch {V}. A removed rail is a safety failure, not a murder."),
        closings: ("A removed safety rail, no warning signs, a foreman who ordered it, and a witness who saw a shove. {V} died in the hopper.", "A wet morning, an argument that was minor, and a foreman who reached out to catch a slipping worker. The State has a coworker's view of a fast moment."),
        timeline: [(0, "7 a.m.: the rail comes off."), (0, "10 a.m.: the argument."), (0, "10:05 a.m.: the fall."), (0, "10:30 a.m.: {V} dies.")],
        identified: "A coworker.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .sympathetic,
        impact: "He had two kids at home.",
        doctrines: ["lesserIncluded"],
        genders: ["V": .male])

    static let ferryPilotBreath = SmallCases.make(
