        state: [E(.forensic, 3, "Breath Result", "A result of .09."), E(.statement, 3, "Deckhand", "'He smelled like a bar.'"), E(.video, 2, "Dock Camera", "{D} unsteady at the ramp.")],
        defense: [E(.statement, 1, "Mouthwash", "{DL} says {D.he} used mouthwash.")],
        role: "Deckhand",
        exam: [.direct("What did you notice before the morning crossing on {DATE}?", "\"{D}, the ferry pilot, smelled of alcohol. I told the others. It smelled like a bar, and that worried us.\""), .direct("What does the dock camera show?", "\"{D} unsteady at the ramp. It shows {D} walking and swaying slightly as {D} approached the boat.\""), .direct("What did the breath test show?", "\"A .09, taken at the dock. That's over the legal limit for a pilot.\""), .direct("Where were you when you smelled alcohol?", "\"On the ramp, tying up before the 6 a.m. crossing. {D} walked past me within arm's length, and the smell was strong and sweet.\""), .direct("What did you do about it?", "\"I told the other deckhand and then radioed the dock office. A supervisor came down and asked {D} to take a breath test at 6:15.\""), .direct("What happened after the test?", "\"The reading was .09, and {D} was suspended at 6:30. We canceled the crossing and moved passengers to another vessel.\""), .cross("{DL} says {D.he} used mouthwash, doesn't {D.he}?", "\"Mouthwash can smell. I can't say that's what it was.\""), .cross("Did {DL} slur speech or act confused?", "\"I don't recall slurred speech. {D} was unsteady, but I wouldn't say confused.\""), .cross("How long between the smell and the test?", "\"A short time. We called it in and the test came soon after. I can't give a minute count.\""), .cross("Did {D} have trouble giving commands?", "\"No. {D} spoke clearly to the crew. The sway at the ramp and the smell are what I noticed.\""), .cross("Have you ever smelled mouthwash on someone?", "\"Yes. This smelled different to me, more like a bar. I cannot swear what it was.\"")],
        defenseRole: "Harbor master",
        defenseExam: [.direct("Did you see {DL} before the crossing?", "\"Yes. I'm the harbor master. I saw {D} come in for work that morning.\""), .direct("Did {DL} seem fit?", "\"Mostly. {D} seemed a bit tired, but nothing I'd flag. I've worked with {D} for years.\""), .direct("Have you ever had an issue with {DL}?", "\"No. {D} has a clean record as far as I know. {D} takes the job seriously.\""), .direct("What do you do as harbor master?", "\"I oversee operations at the dock, manage the schedule, and make sure each crossing has a crew in good condition.\""), .direct("How did {D} look when arriving for work?", "\"Tired, with a flat expression. I did not smell anything, but I was across the lot.\""), .direct("How has {D}'s record been?", "\"Clean for twelve years. No incidents, no complaints, and no write-ups.\""), .cross("Did {DL} seem unsteady?", "\"A little. I noticed it at the ramp. It wasn't dramatic.\""), .cross("Did you smell alcohol?", "\"Not strongly. I wasn't close enough. I can't say either way.\""), .cross("Would you have let {DL} pilot?", "\"I would have asked questions first. I'm glad someone checked.\""), .cross("You never smelled alcohol on {D}?", "\"No, but I did not get close. I am not saying it was not there.\""), .cross("Did you approve the breath test?", "\"Yes. When deckhands raised a concern, I told them to follow the protocol.\"")],
        theory: ("{D} piloted impaired.", "Mouthwash."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} bought a pint the night before.", "The mouthwash bottle was in {DL}'s bag."),
        defendant: [.direct("Why did you smell of alcohol?", "\"I used mouthwash before work. Some brands have alcohol. That's what the deckhands smelled.\""), .direct("Had you been drinking?", "\"Not that morning. I didn't drink before a crossing. I take it seriously.\""), .direct("What about the .09?", "\"I don't understand it. I used mouthwash right before, which can affect a breath test.\""), .direct("How long have you piloted this ferry?", "\"Twelve years. I know the channel and the ramp, and I take pride in a clean safety record.\""), .direct("How did you spend the evening before the crossing?", "\"I got home late from a family matter and slept poorly. I got up at 4:30 and drove to the dock.\""), .direct("What did you do before reporting for the crossing?", "\"I rinsed with mouthwash right before walking down to the ramp. I thought it would freshen me after a short night.\""), .cross("You blew a .09, didn't you?", "\"Yes. I've never had that happen. I think the mouthwash is the reason.\""), .cross("You were unsteady at the ramp, weren't you?", "\"I may have been, from tiredness. I'd had a short night. It's not impairment.\""), .cross("You were about to pilot a ferry, weren't you?", "\"Yes. I would never take a boat out if I was impaired. I'd have called someone.\""), .cross("A breath test of .09 right after rinsing. Do you expect the jury to accept that?", "\"Mouthwash can leave alcohol in the mouth for a short time, and I never considered it before the test.\""), .cross("The camera shows you unsteady. Why?", "\"I was exhausted and stepped on a wet ramp. I do not think it shows I was drunk.\"")],
        openings: ("Before a morning crossing, deckhands smelled alcohol on the ferry pilot, {D}, who looked unsteady at the ramp and blew a .09 at the dock. The State will show the breath result, the dock camera, and the deckhand's account.", "The defense will present a pilot who used mouthwash, a harbor master who found {D} mostly fit, and a test that mouthwash can inflate."),
        closings: ("A pilot about to carry passengers, the smell of a bar, an unsteady walk, and a .09. The test and the deckhands agree. Passengers trust the pilot to be sober, and {D} was not.", "Mouthwash can contain alcohol, and {D} had a short night. The State has not proved {D} was impaired at the helm rather than tired."),
        timeline: [(-1, "The night before."), (0, "6 a.m.: the smell."), (0, "6:15 a.m.: the test."), (0, "6:30 a.m.: suspension.")],
        identified: "A breath test.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let deerCarcassFight = SmallCases.make(
