        timeline: [(0, "Dawn: the buck."), (0, "7:30 a.m.: the dispute."), (0, "7:35 a.m.: the shot."), (0, "8 a.m.: medics.")],
        identified: "Ballistics.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I walk with a cane.",
        doctrines: ["mistakeOfFact"])

