        state: [E(.forensic, 3, "Vial Tests", "Water in six vials."), E(.digital, 3, "Count Records", "Shortages on {D}'s shifts."), E(.statement, 2, "Family", "'Dad was screaming.'")],
        defense: [E(.statement, 1, "Counts", "{DL} says the counts were wrong.")],
        role: "Hospice director",
        exam: [.direct("What did patients at your hospice report?", "\"Uncontrolled pain. Families told us their loved ones were suffering even though they were supposed to be on morphine.\""), .direct("What did your counts show?", "\"Morphine was missing on {D}'s shifts. The count records show shortages tied to those shifts.\""), .direct("What did the vial tests show?", "\"Water in six vials. Someone had refilled morphine vials with water. The patients got none of the pain medicine they needed.\""), .direct("How did families describe the problem?", "\"One family said their parent screamed in pain even after medication was given. Several families raised the same concern within a few weeks.\""), .direct("How did you review the counts?", "\"I compared nurses' signatures, dispensing records, and patient charts. The shortages appeared most often on {D}'s shifts.\""), .direct("What did the lab testing show?", "\"We tested vials from the locked cabinet. Six contained water, and the seals looked reapplied.\""), .cross("{DL} says the counts were wrong, doesn't {D.he}?", "\"Counts can have errors. But six vials had water in them, which a count error doesn't explain.\""), .cross("Did other nurses handle morphine?", "\"Yes. Several nurses had access. The shortages lined up with {D}'s shifts, but others worked those days too.\""), .cross("Did anyone see {DL} swap a vial?", "\"No. No one saw it. I have the counts and the tests.\""), .cross("How many nurses worked the morphine cabinet?", "\"Six nurses had keys. Several had at least one count discrepancy during the period.\""), .cross("Were counts always done by two people?", "\"They are supposed to be, but at night it was often one nurse and an aide, and some were rushed.\"")],
        defenseRole: "Hospice aide",
        defenseExam: [.direct("Who handled morphine at the hospice?", "\"Several nurses. We all signed for it. It wasn't just one person.\""), .direct("Did you work with {DL}?", "\"Yes. {D} was a good nurse. {D} was gentle with patients.\""), .direct("Did you ever see {DL} take anything?", "\"No. I would've reported it.\""), .direct("What is your role at the hospice?", "\"I am an aide. I help with turning patients, feeding, and comfort care, and I sit with families.\""), .direct("How was {D} with the patients?", "\"Gentle and patient. {D} would stay late to hold a hand or talk with a family.\""), .direct("What did you notice about medication counts?", "\"They were done fast. Sometimes the second signature went on a sheet before the count finished.\""), .cross("Were you on shift with {DL} often?", "\"Often. I worked many of the same shifts. That's how I know {D}.\""), .cross("Could someone else have refilled vials?", "\"In theory, yes. Several people had access. I didn't do it, and I don't know who did.\""), .cross("Did you check the counts?", "\"Sometimes. They weren't always perfect. We were busy and counts got rushed.\""), .cross("Did you ever see {D} alone with the cabinet?", "\"Yes, as any nurse would be. I did not see anything wrong.\""), .cross("Did you report concerns about counts to the director?", "\"Once, about general rushing. I did not name anyone.\"")],
        theory: ("{D} took morphine.", "Wrong counts."),
        allocution: "\"I needed help.\"",
        truths: ("{DL} had a history of back pain.", "Another nurse had signed some counts."),
        defendant: [.direct("Did you take morphine from patients?", "\"No. I never took it. I never replaced anything with water. I cared for those patients.\""), .direct("Why do the counts show shortages on your shifts?", "\"The counts were wrong. I worked a lot of shifts, and we were busy. I think errors were made.\""), .direct("What do you know about the water in the vials?", "\"Nothing. I never touched them like that. I don't know how that happened.\""), .direct("How long have you been a hospice nurse?", "\"Eleven years. I chose this work because I wanted to help families through the hardest time.\""), .direct("What are your counts like on a busy night?", "\"We count at the start and end of the shift with another staff member. On a night with many patients, we sometimes sign quickly.\""), .direct("What happened when you heard about the water?", "\"I was shaken. I told the director I would cooperate and give any record I could. I never imagined it.\""), .cross("Six vials had water in them, didn't they?", "\"That's what the tests show. I don't know who did it. I'm horrified.\""), .cross("The shortages were on your shifts, weren't they?", "\"Many were. I worked many shifts. That doesn't mean I took anything.\""), .cross("Patients suffered, didn't they?", "\"I know. I'm heartbroken about it. I would never want that.\""), .cross("Shortages and vials with water. Both are tied to your shifts. How do you explain that?", "\"I worked more shifts than most, and my name is on more records. That does not mean I did it.\""), .cross("You have a history of back pain. Do you take medication?", "\"I have used prescribed medication at times, and I never took patient doses.\"")],
        openings: ("Patients at a hospice reported uncontrolled pain, counts showed morphine missing on {D}'s shifts, and tests found water in six vials. The State will show the counts, the tests, and a family's account.", "The defense will point you to a busy hospice where several nurses handled morphine, counts that were rushed, and no witness who saw {D} take anything."),
        closings: ("Missing morphine on {D}'s shifts and water in six vials. Patients suffered while the medicine meant for them was gone. Someone swapped that medicine for water, and the shifts point to {D}.", "Several nurses handled that morphine, and the counts were rushed. The State has not proved {D}, and not someone else, took it or swapped it."),
        timeline: [(-60, "Complaints begin."), (0, "Week 8: the audit."), (0, "Week 8: vials tested."), (1, "{DL} is suspended.")],
        identified: "Vial tests.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "He suffered at the end.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let courierDriveUpRobbery = SmallCases.make(
        key: "story.courierDriveUpRobbery",
        category: .robbery,
        headlines: ["Armed Men Rob Courier at Bank Drive-Up", "Duffel With $46,000 Taken"],
        law: "dangerousRobbery",
        threshold: 8,
        spec: "Took $46,000 belonging to {V} by endangering and threatening {V.his} life with a firearm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Two armed men took a duffel with $46,000 from a courier at a bank drive-up on {DATE}. {D}, a former armored-car driver, was identified through a phone left at the scene. {DL} says it was stolen.",
        state: [E(.digital, 3, "Phone", "A phone at the scene registered to {D}."), E(.video, 2, "Bank Camera", "Two masked men."), E(.statement, 3, "Courier", "'The shorter one knew my route.'")],
        defense: [E(.statement, 1, "Stolen Phone", "{DL} says the phone was stolen.")],
        role: "Courier",
        exam: [.direct("What happened at the bank drive-up on {DATE}?", "\"Two armed robbers took a duffel with $46,000 from me. They were masked. It all happened fast.\""), .direct("What did one of them say or do?", "\"The shorter one knew my route. That's what stuck with me. Someone who knew exactly where I'd be and when.\""), .direct("How did {DL} come up?", "\"A phone left at the scene is registered to {D}, a former armored-car driver. That's how deputies found {D}.\""), .direct("Walk the jury through the robbery.", "\"I pulled up to the drive-up at 9 a.m. with a duffel for the deposit. Two masked people came from behind a planter, one with a pistol and one with a shotgun.\""), .direct("What did they say?", "\"The shorter one told me to hand over the duffel and not look back. That person spoke as if familiar with my timing and drive-up lane.\""), .direct("What happened after they left?", "\"They ran toward a car I could not see well. I called 911, and a few minutes later a deputy found a phone on the ground near the planter.\""), .cross("Could you see anyone's face?", "\"No. They were masked. I could see height and build. I can't identify anyone by face.\""), .cross("{DL} says the phone was stolen, doesn't {D.he}?", "\"I can't say. I only know a phone registered to {D} was found.\""), .cross("Would many people know your route?", "\"Some who worked in my field. Not many. But it's not impossible for someone else to learn it.\""), .cross("Did either robber use a name?", "\"No. They did not use a name, and they covered their faces.\""), .cross("Can you say how tall the shorter one was?", "\"Around five foot seven. I cannot narrow it more than that.\"")],
        defenseRole: "Former coworker",
        defenseExam: [.direct("How long did you work with {D}?", "\"Three years on the same armored-car company. We rode together and shared a lot of long days, so I know how {D} handles the job.\""), .direct("How would you describe {D}?", "\"Careful and honest. {D} followed every rule, never cut a corner on a pickup, and never complained about the dangerous parts of the job.\""), .direct("Do routes change often at the company?", "\"Rarely. The company adjusts stops now and then, but most of them stay the same for months, which is why a driver who left could still remember a route.\""), .direct("When did {D} leave, and how did it end?", "\"About a year before the robbery. {D} took a warehouse job with steadier hours, and there were no hard feelings that I ever heard of.\""), .direct("What did {D} do when equipment or a phone went missing at work?", "\"Reported it the same day. {D} was strict about that because a lost badge or phone at an armored company is taken very seriously.\""), .direct("What kind of life does {D} lead outside of work?", "\"A quiet one as far as I know. {D} has a family, a steady job, and no history of trouble that I ever heard about.\""), .cross("Was {D} on that exact route in the last year?", "\"No. {D} drove a different one before leaving, so I cannot tell you {D} ever knew the current stops.\""), .cross("So {D} could have known the route a year ago?", "\"Probably, yes. Routes do not change quickly, so someone who drove it then might remember a lot of it.\""), .cross("When exactly did {D} change jobs?", "\"About a year before, but I do not have the date. I would have to check company records to give you the month.\""), .cross("Do you know where {D}'s phone was on the morning of the robbery?", "\"No. I only know what {D} told me about losing it. I was not with {D} that day.\""), .cross("Are you friends with {D}?", "\"We are friendly from work and still talk now and then. I know that colors things, and I am telling you what I saw.\"")],
        theory: ("{D} robbed a courier.", "A stolen phone."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had driven that route.", "{DL} reported the phone stolen after the robbery."),
        defendant: [.direct("Is that your phone at the scene?", "\"It was registered to me, but it was stolen. I didn't have it that day.\""), .direct("Did you rob the courier?", "\"No. I would never rob a bank courier. I used to do that job. I know how dangerous it is.\""), .direct("Do you know the courier's route?", "\"I used to drive a route. I changed jobs a year ago. I don't know what the route is now.\""), .direct("What was your job before?", "\"I drove an armored car for six years and then took a job at a warehouse. I changed jobs about a year before the robbery.\""), .direct("Where was your phone that morning?", "\"I did not have it. I noticed it was missing the day before and assumed I left it at the gym.\""), .direct("What did you do when deputies called you?", "\"I told them I had lost the phone and gave my address. I did not hide anything.\""), .cross("You're a former armored-car driver, aren't you?", "\"Yes. I know the work. But that's why I'd never do this. I know what it does to the drivers.\""), .cross("The phone was registered to you, wasn't it?", "\"Yes. That's my number. I don't know how it got there.\""), .cross("You left that job a year ago, didn't you?", "\"Yes. I had no reason to know the current route. I moved on.\""), .cross("The phone was at the robbery scene. How do you explain that?", "\"I cannot. If someone took it, they could have dropped it there. I did not go to that bank that morning.\""), .cross("You knew courier routes. Isn't that how a robber picks a target?", "\"I knew routes from a year earlier. I would not use that knowledge to rob someone.\"")],
        openings: ("Two masked, armed people took a $46,000 duffel from a courier at a bank drive-up. A phone left at the scene is registered to {D}, a former armored-car driver. The State will show the phone, the bank camera, and the courier's account.", "The defense will present a phone that was stolen, a former driver who changed jobs a year ago, and masked robbers no one could identify."),
        closings: ("A phone registered to {D} left at the scene, a robber who knew the route, and a defendant who once drove it. Those facts point to {D}.", "A phone is not a person. {D} says it was stolen, left that job a year ago, and no one saw a face. The State has not proved {D} was at that drive-up."),
        timeline: [(0, "9 a.m.: the robbery."), (0, "9:05 a.m.: the phone is found."), (1, "{DL} is identified."), (2, "{DL} is arrested.")],
        identified: "A phone.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I haven't worked since.",
        doctrines: ["alibi"],
        genders: ["D": .male])

    static let carWashToyGun = SmallCases.make(
