        defense: [E(.statement, 1, "Prank", "{DL} says it was a prank.")],
        role: "Car wash attendant",
        exam: [.direct("What happened at your car wash on {DATE}?", "\"A teen pointed what looked like a pistol at me and took $240. I thought I would die.\""), .direct("What does your camera show?", "\"{D} pointing a pistol at me. It shows the whole thing, and you can see my reaction.\""), .direct("What did deputies find?", "\"A toy pistol in {D}'s bag, with the orange tip removed. It looked real to me.\""), .direct("Where were you standing when {D} walked up?", "\"At the pay booth at the end of the wash tunnel, counting the afternoon's cash. It was around 4 p.m. and only one car was in the bay.\""), .direct("What did {D} say and do?", "\"{D} pulled a pistol from a bag, pointed it at my chest, and said to give up the cash drawer. My hands shook, and I handed over the money.\""), .direct("How did you feel and what did you do afterward?", "\"I thought I was about to be shot. I locked myself in the office and called 911 once {D} left, and I could not stop trembling for an hour.\""), .cross("It was a toy, wasn't it?", "\"I know that now. At the time it looked like a real gun. The orange tip was missing.\""), .cross("{DL} says it was a prank, doesn't {D.he}?", "\"It didn't feel like a prank to me. I was terrified.\""), .cross("Were you hurt?", "\"No. But I was shaken for days. I thought my life was ending.\""), .cross("Did {D} ever say anything threatening beyond giving up the cash?", "\"No. {D} did not threaten to shoot. The gun and the demand were all it took.\""), .cross("Did {D} seem to enjoy it?", "\"No. {D} looked nervous and kept glancing at the street. I remember thinking {D} was very young.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Were you with {DL} that day?", "\"Yes. We were hanging out. {D} had a toy pistol, and we were joking around.\""), .direct("What was the plan?", "\"A dare. Someone said {D} wouldn't go up to the car wash with it. It was supposed to be funny.\""), .direct("Did {DL} say anything about the money?", "\"Not at first. It was a dare. I didn't think the money was part of it.\""), .direct("How long have you known {D}?", "\"Since middle school. We hang out after school and on weekends. {D} is usually the quiet one.\""), .direct("How did the dare start?", "\"Someone said {D} would never walk up to a stranger with the toy. {D} looked at us and said, 'Watch me.'\""), .direct("What did you see {D} do at the car wash?", "\"{D} walked up to the attendant, pulled out the toy, and said something. The attendant handed over the money.\""), .cross("Did {DL} take the cash?", "\"Yes. {D} took it. I saw {D} take the money.\""), .cross("Did you stop {DL}?", "\"No. That is on me. I thought it was a joke until it wasn't.\""), .cross("Did {DL} point the toy at the attendant?", "\"Yes. I saw it. It looked real, and I understood why the attendant was afraid.\""), .cross("Did you think the toy looked real?", "\"Up close, yes, because the tip was off. I did not think about that until after.\""), .cross("What did {D} do right after?", "\"{D} walked back to us pale and said it was a mistake. We argued about taking the money back.\"")],
        theory: ("{D} robbed an attendant.", "A prank."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} spent the money on a game.", "{DL} gave the money back within the hour."),
        defendant: [.direct("Why did you point the toy gun at the attendant?", "\"It was a dare from my friends. I figured everyone would laugh about it by dinner. I didn't think about how scary it would be.\""), .direct("Did you mean to rob the car wash?", "\"No. It was a prank. I never planned to take money.\""), .direct("How did the money change hands?", "\"The attendant handed me the cash when I asked. I took it. I know that's the worst part.\""), .direct("How did the dare come about?", "\"A group of us were hanging out and someone said I would never do something crazy. I had the toy gun in my bag, and I said yes without thinking.\""), .direct("What were you thinking as you walked into the car wash?", "\"That it would be a quick prank and we would laugh. I did not think about how scared someone would be.\""), .direct("What happened after you left?", "\"I felt sick right away. I told my friends I wanted to take it back, and I went back to the car wash within the hour.\""), .cross("You took $240, didn't you?", "\"Yes. I did. It was part of the dare, and I shouldn't have.\""), .cross("The orange tip was removed, wasn't it?", "\"Yes. I took it off so it looked real. That was stupid.\""), .cross("The attendant thought you'd kill {V.him}, didn't {V.he}?", "\"I know now. I'm very sorry. I wasn't thinking.\""), .cross("You took off the orange tip so it would look real. Why?", "\"To make the prank better. It was a stupid idea, and it made things much worse.\""), .cross("Why did you take cash if it was only a prank?", "\"It was part of the dare, and I did not think. I know that makes it a robbery in the eyes of the law.\"")],
        openings: ("A teenager, {D}, pointed what looked like a pistol at a car wash attendant and took $240. It was a toy with the orange tip removed. The State will show the car wash camera, the toy in {D}'s bag, and the attendant's account.", "Jurors will also see a dare among friends, a toy gun, and a teen who did not understand how frightening it would be. This was a foolish prank."),
        closings: ("A gun that looked real, a frightened attendant, and $240 taken. The orange tip was missing, and the attendant believed {V.he} would die. That terror is what this crime protects against.", "A dare and a toy, with no plan to hurt anyone. The State has not proved {D} meant to rob the car wash rather than prank it."),
        timeline: [(0, "4 p.m.: the pointing."), (0, "4:01 p.m.: the cash."), (0, "5 p.m.: the return."), (1, "{DL} is arrested.")],
        identified: "A camera.",
        mood: .sympathetic,
        impact: "I still shake.",
        doctrines: ["lesserIncluded"],
        genders: ["D": .male])

    static let laundromatClosingRobbery = SmallCases.make(
