    static let bakeryDawnRobbery = SmallCases.make(
        key: "story.bakeryDawnRobbery",
        category: .robbery,
        headlines: ["Man With Revolver Robs Bakery at Dawn", "Till and Safe Emptied"],
        law: "dangerousRobbery",
        threshold: 8,
        spec: "Took $3,100 belonging to {V} by endangering and threatening {V.his} life with a firearm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A man with a revolver robbed a bakery owner at dawn on {DATE}. A delivery driver identified {D}, a former employee. {DL} says he was asleep.",
        state: [E(.video, 3, "Bakery Camera", "A man with a revolver."), E(.statement, 3, "Delivery Driver", "'I know him.'"), E(.physical, 2, "Revolver", "Found in a drainage pipe.", .search)],
        defense: [E(.statement, 1, "Asleep", "{DL} says {D.he} was asleep.")],
        role: "Bakery owner",
        exam: [.direct("What happened at your bakery at dawn on {DATE}?", "\"A person with a revolver came in and robbed me. The bakery camera captured it.\""), .direct("Who did the delivery driver identify?", "\"{D}, a former employee. The driver said, 'I know that one,' meaning {D}, from how {D} moved and stood.\""), .direct("What was found afterward?", "\"A revolver in a drainage pipe. Deputies recovered it.\""), .direct("What time did the robbery happen and what was going on?", "\"About 5:10 in the morning. I was alone in the front kneading dough when someone came through the back door with a revolver and demanded the cash box.\""), .direct("What did you see of the robber?", "\"A figure in a dark hoodie with a bandana across the nose and mouth. I saw the eyes and the way the person moved but no full face.\""), .direct("What did the delivery driver say?", "\"The driver arrived a minute later and said, 'I know that one,' as the robber ran past. The driver named {D}, who worked for me for two years.\""), .cross("Could you see the robber's face?", "\"Not clearly. The person wore something to cover part of it. I recognized the way of moving, not the face.\""), .cross("{DL} says {D.he} was asleep, doesn't {D.he}?", "\"I can't say where {D} was. I only know what the camera and the driver say.\""), .cross("Did {DL} have a grudge?", "\"{D} is a former employee. I let {D} go. I can't say that was the reason.\""), .cross("Did you recognize the robber yourself?", "\"The build looked like {D}'s, but I will not say I knew for certain. The camera is the thing that bothers me.\""), .cross("Why did you let {D} go?", "\"Persistent lateness and missed shifts. We parted on poor terms about a month before.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("Do you live with {DL}?", "\"Yes. We share an apartment. I know when {D} comes and goes.\""), .direct("Where was {DL} at dawn?", "\"In bed. I saw {D} there when I got up. {D} was asleep.\""), .direct("Was {DL} awake at any point?", "\"Briefly, I think. {D} got up for water and went back to bed.\""), .direct("How long have you lived with {D}?", "\"Two years. We split rent and share a kitchen and a bathroom. I know {D}'s routines pretty well.\""), .direct("What do you remember about that morning?", "\"I woke up around five, got water, and saw {D}'s door open and {D} in bed. I went back to my room.\""), .direct("What are {D}'s habits in the morning?", "\"{D} sleeps late. I have rarely seen {D} awake before eight, and then only when work requires it.\""), .cross("Were you awake the whole time?", "\"No. I was asleep part of the time. I can't say what happened while I slept.\""), .cross("What time did you see {DL}?", "\"Early morning. Before dawn. I didn't check the clock.\""), .cross("Could {DL} have left and returned?", "\"I suppose so. I'd probably have heard the door. I'm not certain.\""), .cross("Did you look at the clock?", "\"I think it was about 5:20. I did not check. It was dark and I was barely awake.\""), .cross("How can you be sure it was {D} in the bed?", "\"I saw the shape and the hair. It was dark, but I know who lives there.\"")],
        theory: ("{D} robbed a bakery.", "Asleep."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had been fired a month earlier.", "A roommate saw {DL} in bed at 5:20."),
        defendant: [.direct("Where were you at dawn?", "\"In bed asleep. I don't get up that early. I have a roommate who can say I was home.\""), .direct("Did you rob the bakery?", "\"No. I'd never rob the place where I used to work. I liked the job.\""), .direct("How do you explain the driver's identification?", "\"The driver saw someone masked and thought of me. They're mistaken. I wasn't there.\""), .direct("What was your time at the bakery like?", "\"Two years of early mornings, loading ovens and boxing orders. I liked the work, and I was upset when I was let go.\""), .direct("What do you do now?", "\"Odd jobs and part-time shifts. I sleep late and rarely get up before eight, which is why I would not be out at 5 a.m.\""), .direct("Who was home that morning?", "\"My roommate, who sleeps in the next room. We keep the apartment door locked and the keys by the front.\""), .cross("You used to work at the bakery, didn't you?", "\"Yes. I know the layout. That's why people think of me. But I wasn't there.\""), .cross("The driver says it's you, doesn't the driver?", "\"Yes. I don't know why. It wasn't me.\""), .cross("Your roommate can't say where you were every minute, can your roommate?", "\"No. We were both asleep for part of it. I know it's not perfect.\""), .cross("You were angry about being fired, weren't you?", "\"I was disappointed, and I said so. I would not rob someone over that.\""), .cross("The driver says it was you. Why would a driver lie?", "\"I do not think the driver lied. I think the driver saw a masked person and picked the first person who came to mind.\"")],
        openings: ("At dawn, a person with a revolver robbed a bakery owner. A delivery driver identified {D}, a former employee, and a revolver was found in a drainage pipe. The State will show the bakery camera and the driver.", "The defense will point you to a person asleep at home, a roommate who saw {D} in bed, and a masked robber whose face no one saw."),
        closings: ("A robbery at dawn, a driver who knows {D}, and a former employee who knew the bakery. Those who know {D} recognized {D}. That is why the driver was so sure.", "A masked robber and an identification by movement. {D} was in bed asleep, and a roommate says so. The State has not proved it was {D}."),
        timeline: [(-30, "{DL} is fired."), (0, "5:10 a.m.: the robbery."), (0, "5:20 a.m.: the roommate sees {DL}."), (1, "{DL} is arrested.")],
        identified: "A delivery driver.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I sold the shop.",
        doctrines: ["alibi"],
        genders: ["D": .male])

    static let armoredRoutePlot = SmallCases.make(
        key: "story.armoredRoutePlot",
        category: .robbery,
        headlines: ["Guards and Driver Plotted Cash Theft From Armored Route, Texts Show", "Plan Laid Out in Group Chat"],
        law: "conspiracyRobbery",
        threshold: 7,
        spec: "Conspired to commit robbery with a dangerous weapon of an armored vehicle, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Texts show {D} and two others planned to rob their armored route on {DATE}. Deputies arrested them at a staging site with masks. {DL} says it was talk.",
        state: [E(.digital, 3, "Group Chat", "'We take the Tuesday load.'"), E(.physical, 3, "Staging Site", "Masks and zip ties.", .search), E(.statement, 2, "Informant", "'{D} drew the map.'")],
        defense: [E(.statement, 1, "Talk", "{DL} says it was talk.")],
        role: "SBI agent",
        exam: [.direct("What did your investigation find about {DL} and the armored route?", "\"Group texts show {D} and two others planned to rob their own armored route. 'We take the Tuesday load.'\""), .direct("What did deputies find at the staging site?", "\"Masks and zip ties. The three were arrested there. That's the staging site we'd been told about.\""), .direct("What did your informant say?", "\"That {D} drew the map. The informant said {D} laid out the route in detail.\""), .direct("How did the investigation begin?", "\"A coworker reported a group chat on a company phone with talk of taking the Tuesday load. We obtained the messages through a warrant.\""), .direct("What did the chat contain?", "\"Messages about route times, the number of guards, and where to park. One message from {D} said, 'We take the Tuesday load.'\""), .direct("How did the arrest unfold?", "\"We watched the staging site on Tuesday morning. Three people arrived in a truck with masks and zip ties and were taken into custody without incident.\""), .cross("{DL} says it was talk, doesn't {D.he}?", "\"But people who are only talking don't show up at a staging site with masks.\""), .cross("Were any weapons recovered?", "\"No weapons were found at the site. I won't say otherwise.\""), .cross("Did {DL} say anything about carrying out the plan?", "\"The texts show the plan. I have no recording of {D} saying 'we do it now.'\""), .cross("Did {D} say anything on arrest about robbing anything?", "\"No. {D} said they were hunting, which fit the camo, and asked for a lawyer.\""), .cross("Did you recover any firearm or cash?", "\"No. We found no weapon and nothing was taken. The case depends on the chat, the map, and the items at the site.\"")],
        defenseRole: "Hunting buddy",
        defenseExam: [.direct("How long have you hunted with {D}?", "\"About six years. We go out most weekends in season and trade tips on gear, stands, and weather.\""), .direct("What did you see {D} pack for the trip?", "\"Camo clothing, face masks, binoculars, and a bag of tools and ties for the stand. It was the usual gear for that kind of hunt.\""), .direct("What are camo face masks for?", "\"They hide your face from deer. Hunters pull them on at the last moment, and it is common to carry several.\""), .direct("How did the three of them talk about their jobs?", "\"With dark humor. They complained about long routes and joked about the money they handled, but I never took it seriously.\""), .direct("What did {D} say about the trip that week?", "\"That it was going to be a good weekend for hunting. {D} was excited about a new stand and talked about little else.\""), .direct("What is {D}'s character as you know it?", "\"Level-headed. {D} has never shown any interest in violence and is the one who calms people down when tempers flare.\""), .cross("Were you at the staging site?", "\"No. I was not there. I heard about the arrest from others afterward.\""), .cross("Did you hear them joke about robbing an armored car?", "\"Yes, a couple of times. I assumed it was gallows humor and did not think anyone meant it.\""), .cross("Were any weapons on the truck?", "\"I do not know. I did not see the truck that morning.\""), .cross("Are you a close friend of {D}?", "\"Yes, and I know that matters. I am telling you what I know about how {D} talks and acts.\""), .cross("Did {D} ever mention a real plan?", "\"No. Never to me. If {D} had said anything serious, I would have reported it.\"")],
        theory: ("{D} conspired to rob.", "Talk."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} drew a route map.", "No weapons were recovered."),
        defendant: [.direct("Did you plan to rob an armored car?", "\"No. We talked about it. It was just talk. We never really meant to do it.\""), .direct("Why were you at the site?", "\"We were hunting. We were out in the field. The masks were camo for hunting.\""), .direct("What about the map?", "\"I sketched a route. I often draw maps of places. It wasn't a plan to rob anyone.\""), .direct("How do you know the other two people?", "\"We work for the same company and hunt together on weekends. We talk a lot about work, and we joke about everything.\""), .direct("What did you mean by 'We take the Tuesday load'?", "\"It was a joke about how much work a Tuesday route is. Someone made a bank-robber crack and I answered it.\""), .direct("Why did you draw the map?", "\"I drew it to show a new driver how the stops line up. I draw maps constantly. It was not a plan to rob anyone.\""), .cross("The texts say 'We take the Tuesday load,' don't they?", "\"Yes. It's in the chat. I thought it was joking around.\""), .cross("You drew a map of the armored route, didn't you?", "\"Yes. I knew it from work. I drew it for a joke.\""), .cross("You were arrested with masks and zip ties, weren't you?", "\"The masks were camo. The zip ties were for gear. I know how it looks.\""), .cross("You wrote about who would drive and who would watch. Joking?", "\"We were making a joke of it and egging each other on. I did not think it was a plan.\""), .cross("You were at a staging site with masks and zip ties. Why?", "\"We were going to a hunting spot. The masks were camo, and the zip ties are for gear and gates.\"")],
        openings: ("Texts show {D} and two others planned to rob their own armored route, and deputies arrested them at a staging site with masks and zip ties. The State will show the group chat, the site, and an informant.", "The defense will present a hunting trip, camo masks, and talk among friends that never became a plan. No weapons were found. Talk is not a conspiracy."),
        closings: ("A plan in writing, a map, and three people arrested at a staging site with masks and zip ties. This was a plan, and it was ready to go.", "Camo masks, hunting gear, and loose talk. No weapons were found, and nothing was robbed. The State has not proved a real agreement to commit a robbery."),
        timeline: [(-14, "The chat begins."), (0, "Tuesday: staging."), (0, "Tuesday: arrests."), (30, "Indictment.")],
        identified: "A chat.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let trophyShotguns = SmallCases.make(
        key: "story.trophyShotguns",
        category: .property,
        headlines: ["Intruder Takes Shotgun Collection From Occupied Farmhouse", "Family Sleeps Upstairs"],
        law: "burglary1",
        threshold: 8,
        spec: "Broke and entered an occupied dwelling of {V} at night with intent to commit larceny, on {DATE}.",
        ages: 18...60,
        victim: true,
