        state: [E(.statement, 3, "Neighbor", "'{D}'s truck at 2 a.m.'"), E(.physical, 3, "Truck Search", "Two stolen shotguns.", .search), E(.document, 2, "Inventory", "Eleven shotguns missing.")],
        defense: [E(.statement, 1, "Lost", "{DL} says {D.he} was lost on the road.")],
        role: "Homeowner",
        exam: [.direct("What happened at your farmhouse?", "\"While my family slept, someone took eleven shotguns from the den. We found them gone in the morning.\""), .direct("How did {D} come into the case?", "\"A neighbor saw {D}'s truck on the road at 2 a.m. A search of the truck later found two of the stolen shotguns.\""), .direct("What does the inventory show?", "\"Eleven shotguns missing. I gave deputies the serial numbers, and two matched those in the truck.\""), .direct("When and how did you discover the theft?", "\"At about 7 a.m., when my family woke. The den door was open and the gun cabinet, which has a weak lock, was empty.\""), .direct("How did the neighbor's report come in?", "\"The neighbor called deputies and said {D}'s truck passed twice on our road around 2 a.m. with its lights low.\""), .direct("What did deputies recover?", "\"They stopped {D}'s truck later that morning and found two of my shotguns behind the seat. The serial numbers matched my inventory.\""), .cross("Did anyone see {D} at your house?", "\"No. The neighbor saw the truck on the road, not at my house.\""), .cross("{D} says {D.he} was lost, doesn't {D.he}?", "\"That is what {D} says. The road is a back road, and it is easy to get lost, I suppose.\""), .cross("Did you know {D}?", "\"No. I had never met {D} before this.\""), .cross("Did you hear or see anything during the night?", "\"No. We were all asleep. A creaky floor in the den would have woken me, but I slept through.\""), .cross("Are the other nine guns accounted for?", "\"No. Nine are still missing. I do not know where they went.\"")],
        defenseRole: "Truck mechanic",
        defenseExam: [.direct("Was the GPS in {D}'s truck working?", "\"Yes. It was working properly. It recorded where the truck went that night.\""), .direct("What did the GPS show?", "\"Several stops. One of them was elsewhere than the farm road, which fits what {D} said.\""), .direct("Did you check the system yourself?", "\"Yes. I serviced the truck and checked the GPS. It was accurate.\""), .direct("How long have you worked on {D}'s truck?", "\"Five years. I do oil changes, brakes, and the electronics, including the GPS unit {D} had installed.\""), .direct("How does the GPS work?", "\"It pings the truck's location every minute and stores the trail. I downloaded the data for that night.\""), .direct("What did the trail show?", "\"The truck went back and forth on that road and then made a stop at a different location about two miles away.\""), .cross("Does the GPS show a stop near the farmhouse?", "\"It shows the truck on that road. I do not recall a stop at the house.\""), .cross("Could the GPS have been turned off?", "\"It can be, but it was on that night.\""), .cross("How many stops were there overall?", "\"Several, in different places. I did not map each one.\""), .cross("Does the trail show a stop at the farmhouse?", "\"No stop at the farmhouse. It shows the truck passing on that road.\""), .cross("Could someone have tampered with the data?", "\"I see no sign of it. The record looks like normal GPS data.\"")],
        theory: ("{D} stole a gun collection.", "A lost driver."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} owed $5,000 to a dealer.", "The truck's GPS shows a stop elsewhere."),
        defendant: [.direct("Did you break into the farmhouse?", "\"No. I did not break into anyone's house. I was lost on a back road that night.\""), .direct("Why were you on that road?", "\"I was lost. I was driving at night and missed a turn. I do not know the area.\""), .direct("How did you end up with two shotguns?", "\"They were in my truck. I do not know how. I did not take them from that house.\""), .direct("Why were you out at 2 a.m.?", "\"I worked late, and my usual route home was closed for road work. I turned onto a back road to find a way around and got lost.\""), .direct("What did you do on that road?", "\"I drove slowly looking for signs and doubled back twice. I stopped once to check my phone map and kept going.\""), .direct("How did the shotguns get in your truck?", "\"I do not know. I rarely look behind the seat. If someone put them there, I never saw it.\""), .cross("You owed $5,000 to a dealer, didn't you?", "\"Yes. I owed money. That does not mean I stole guns.\""), .cross("Two stolen shotguns in your truck. How do you explain that?", "\"I cannot explain it. I did not know they were there.\""), .cross("A neighbor saw your truck at 2 a.m. Why were you out then?", "\"I was driving home. I had worked late and got lost.\""), .cross("You owed money to a dealer and two stolen shotguns were in your truck. Isn't that a motive and proof?", "\"It looks like both, but I did not steal them. I was lost on a back road.\""), .cross("If you were lost, why didn't you use your GPS?", "\"I did. It is on my phone and in the truck. It will show where I went.\"")],
        openings: ("An intruder took eleven shotguns from a farmhouse den while the family slept. A neighbor saw {D}'s truck on the road at 2 a.m., and two stolen shotguns were found in it.", "The defense evidence will establish that {D} was lost on a back road, that GPS shows a stop elsewhere, and that no one saw {D} at that house."),
        closings: ("Eleven shotguns gone, {D}'s truck on the road at 2 a.m., two stolen guns inside it, and a $5,000 debt. These facts fit together.", "A lost driver on a back road and a GPS that shows another stop. Two guns in a truck do not prove {D} broke into a home."),
        timeline: [(0, "2 a.m.: the truck."), (0, "2:30 a.m.: the guns."), (0, "7 a.m.: the family wakes."), (1, "{DL} is stopped.")],
        identified: "A neighbor and a search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "They were my father's.",
        doctrines: ["searchSeizure"])

    static let funeralHomeJewelry = SmallCases.make(
        key: "story.funeralHomeJewelry",
        category: .property,
        headlines: ["Thieves Break Into Funeral Home and Take Jewelry From the Deceased", "Back Door Pried at Night"],
