    static let beeHiveTheft = SmallCases.make(
        key: "story.beeHiveTheft",
        category: .property,
        headlines: ["Thirty Beehives Stolen During Pollination Season", "Beekeeper Loses Season's Income"],
        law: "felonyLarceny",
        threshold: 8,
        spec: "Took and carried away property valued at $12,000 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Thirty beehives were taken from an orchard on {DATE}. {D}, a beekeeper, had hives with matching brand marks. {DL} says the hives were {D.his}.",
        state: [E(.physical, 3, "Hive Boxes", "Brand marks match {V}.", .search), E(.video, 2, "Orchard Camera", "A truck at night."), E(.document, 3, "Hive Registry", "Thirty registered to {V}.")],
        defense: [E(.statement, 1, "Own", "{DL} says the hives were {D.his}.")],
        role: "Orchard owner",
        exam: [.direct("What was taken from your orchard on {DATE}?", "\"Thirty beehives. They were registered to me, and I rely on them to pollinate the trees every season.\""), .direct("What does your orchard camera show?", "\"A truck at night near the hives. The image is dark but it shows a truck and activity at the hive stands.\""), .direct("What ties {DL} to the hives?", "\"{D}, a beekeeper, had hive boxes with brand marks that match mine. The hive registry lists thirty registered to me.\""), .direct("How did you notice the hives were gone?", "\"I drove into the orchard at about 6 a.m. in blossom season and the rows where the hives sat were bare. Only flattened grass and pallet marks were left.\""), .direct("Why are the hives valuable to you?", "\"Bees pollinate the trees. I rent hives each spring, and each one runs a few hundred dollars. Thirty gone meant a poor crop and lost income.\""), .direct("Describe the brand marks for the jury.", "\"Every box in my yard is branded with my mark burned into the wood, and the registry lists thirty boxes under my name.\""), .cross("{DL} says the hives were {D.his} own, doesn't {D.he}?", "\"I can only tell you the brand marks on the boxes and what the registry shows.\""), .cross("Did you see the truck's driver?", "\"No. The camera shows a truck, but not the driver. I couldn't say who it was.\""), .cross("Are brand marks easy to copy?", "\"I suppose someone could mark a box. But the marks on these matched mine exactly.\""), .cross("Did you ever sell hives to {D}?", "\"Years ago, a few. I do not recall how many, and I do not have a record of the boxes I sold.\""), .cross("Could {D} own boxes with marks like yours for innocent reasons?", "\"Possibly, if {D} bought used equipment. But the marks on these boxes matched mine, and several were in my yard before they vanished.\"")],
        defenseRole: "Fellow beekeeper",
        defenseExam: [.direct("Are you a beekeeper too?", "\"Yes. I've kept bees for many years and I know most of the keepers around here.\""), .direct("Has {DL} sold hives?", "\"Yes. {D} sells hives from time to time. I've seen the transactions at local meetings.\""), .direct("Do beekeepers swap boxes?", "\"Often. We buy and sell used equipment all the time, and marks get mixed.\""), .direct("How long have you kept bees?", "\"Almost thirty years. I belong to the county beekeepers' association and know most of the keepers around here.\""), .direct("How common is it to find a mark from another keeper on a box?", "\"Very common. We buy and sell used boxes all the time, and a mark can follow a box through five owners.\""), .direct("What do you know about {D}'s equipment?", "\"{D} has a large yard with boxes of mixed vintage. Some carry other keepers' marks, which is normal.\""), .cross("Did {DL} sell thirty hives?", "\"Maybe. I don't know the exact number. It would be a big sale.\""), .cross("Did you see where {DL}'s hives came from?", "\"No. I only know {D} has hives. I don't know their history.\""), .cross("Could the marks on {DL}'s boxes have been copied?", "\"I can't say. Marks can be burned or painted. I haven't examined these.\""), .cross("Did you inspect the boxes in {D}'s yard after the theft?", "\"No. I only know what {D} told me and what I saw before. I have not examined them since.\""), .cross("Could thirty hives be moved in one night?", "\"With two or three people and a truck, yes. It would be hard for one person.\"")],
        theory: ("{D} took hives.", "His own."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} repainted three boxes.", "{DL} had sold hives to {V} earlier."),
        defendant: [.direct("Whose hives were those on your property?", "\"Mine. I'm a beekeeper, and I've kept hives for years. I moved some to my own yard before that night.\""), .direct("Why do the boxes carry brand marks like {V}'s?", "\"Many beekeepers use similar marks, and I may have bought used boxes. I don't know why they match.\""), .direct("Did you take thirty hives from the orchard?", "\"No. I did not. I'd never steal from another beekeeper. We all depend on the same bees.\""), .direct("How did you get into beekeeping?", "\"I learned from a mentor and have kept hives for more than twenty years. I rent them for pollination and sell honey in the fall.\""), .direct("Where did your hives come from?", "\"Some I built, and some I bought used from other keepers. Over time I accumulated boxes with different marks.\""), .direct("Did you repaint any boxes?", "\"A few. I repainted three that were weathered. I never covered a brand to hide it.\""), .cross("Thirty hives is a large number to move, isn't it?", "\"It is. I couldn't have moved that many alone in one night. That's another reason I say it wasn't me.\""), .cross("The registry lists thirty hives to {V}, doesn't it?", "\"That's what it says. I didn't check the registry. I assumed mine were mine.\""), .cross("Your boxes carry {V}'s marks, don't they?", "\"Some do. I may have bought used equipment. I can't explain more than that.\""), .cross("You can't tell us who you bought the marked boxes from. Why not?", "\"Because I bought from several people at yard sales and auctions, and I did not keep paperwork.\""), .cross("A truck was filmed at the orchard at night. Was it yours?", "\"I was home that night. I do not know whose truck it was.\"")],
        openings: ("Thirty beehives registered to {V} were taken from an orchard at night. A truck is on the orchard camera, and {D}, a beekeeper, had boxes with brand marks matching {V}'s. The State will show the boxes and the registry.", "The defense will point you to a beekeeper who owns hives and buys used equipment, a fellow beekeeper who knows how boxes trade hands, and a camera that cannot identify the truck."),
        closings: ("Thirty hives registered to {V}, a truck at night, and {D}'s boxes bearing {V}'s marks. The registry and the marks agree, and the beekeeper who owns the hives lost a season of work.", "Beekeepers trade used boxes constantly, and a brand mark on a box is not a signature. The State has not proved {D} took thirty hives from the orchard."),
        timeline: [(-90, "{DL} sells hives."), (0, "Night: the truck."), (1, "The orchard owner."), (3, "The search.")],
        identified: "A registry.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let hardwareGreenhouseGrow = SmallCases.make(
        key: "story.hardwareGreenhouseGrow",
        category: .drugs,
        headlines: ["Greenhouse Grow Found Behind Hardware Store", "Plants Under Grow Lights"],
        law: "possMarijuana",
