        defense: [E(.statement, 1, "Tenant", "{DL} says a tenant added the plants.")],
        role: "Deputy",
        exam: [.direct("What did you find behind the hardware store on {DATE}?", "\"A greenhouse holding 64 marijuana plants. We seized them and a lab report confirmed they were marijuana.\""), .direct("Who leases the greenhouse?", "\"{D}. The lease lists {D} as the leaseholder. That means the space is under {D}'s control.\""), .direct("How did you get there?", "\"We were following a tip about the greenhouse. We looked inside with the proper authority and found the plants growing.\""), .direct("What tip led you to the greenhouse?", "\"A caller reported a strong skunk-like smell behind the hardware store and bright lights on at night. We watched the building for two days.\""), .direct("What did you see on entering?", "\"Long benches with 64 marijuana plants in various stages, along with fans, lights, and timers. A few tomato plants stood near the door.\""), .direct("How did the lab confirm what the plants were?", "\"We sent samples, and the lab report identified them as marijuana. It also counted the plants by weight and stage.\""), .cross("{DL} says a tenant added the plants, doesn't {D.he}?", "\"I haven't been able to identify a tenant. I can only tell you who holds the lease.\""), .cross("Did you see {DL} tend the plants?", "\"No. I only found the plants. I did not observe anyone working with them.\""), .cross("Were tomatoes also growing in the greenhouse?", "\"I recall some other plants. I focused on the marijuana. I can't say how many tomatoes.\""), .cross("How do you know {D} was the grower and not just the leaseholder?", "\"I do not know that. I know {D} leases the space and that the plants were growing inside.\""), .cross("Was anyone in the greenhouse when you arrived?", "\"No. The building was locked and empty. We entered with a warrant at 10 a.m.\"")],
        defenseRole: "Hardware clerk",
        defenseExam: [.direct("Do you work at the hardware store?", "\"Yes. I'm a clerk there. The greenhouse is out back, and I see it daily.\""), .direct("Did {DL} grow tomatoes?", "\"Yes. I saw tomato plants in there. {D} talked about tomatoes often.\""), .direct("Did you see anyone else in the greenhouse?", "\"Sometimes a person came by. I didn't know who. I figured it was help.\""), .direct("How well do you know {D}?", "\"{D} has shopped here for years. {D} buys potting soil, ties, and fertilizer for the tomato beds.\""), .direct("What kind of purchases did {D} make this season?", "\"Soil and plant food, and a few new fans. Nothing that stood out as unusual for a gardener.\""), .direct("Did you ever see another person with {D}?", "\"Once or twice. A person in a cap came in with {D} to pick up fertilizer and said little.\""), .cross("Did {DL} grow only tomatoes?", "\"Unsure. I never went in myself. I only saw from the door.\""), .cross("Did you see the marijuana?", "\"No. I never saw it. I didn't see any.\""), .cross("How often was {DL} there?", "\"Fairly often. I can't give you a number. It was part of {D}'s routine.\""), .cross("Did you sell grow lights to {D}?", "\"I sell lights to a lot of people. I do not recall a specific sale to {D}.\""), .cross("Did you know about the marijuana?", "\"No. I never went inside the greenhouse. I only saw the tomatoes through the front door.\"")],
        theory: ("{D} grew marijuana.", "A tenant."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} bought grow lights.", "The tenant paid in cash."),
        defendant: [.direct("What do you grow in your greenhouse?", "\"Tomatoes, mostly. I lease the greenhouse for that. It's a business I've been building slowly.\""), .direct("Whose plants were the marijuana ones?", "\"A tenant's. I let someone use part of the space. I didn't know what they planted.\""), .direct("Did you grow marijuana?", "\"No. I never planted it, watered it, or sold it. I would have kicked the tenant out if I knew.\""), .direct("How long have you leased the greenhouse?", "\"About two years. I use it to grow tomatoes and peppers and sell them at the farmers market.\""), .direct("What can you tell us about the tenant?", "\"I agreed to let someone use a corner of the space for starting plants. We shook on a price per month and the tenant paid in cash.\""), .direct("Did you visit the greenhouse often?", "\"A couple of times a week for watering and picking. I mostly stayed near my tomatoes and did not look at the far benches.\""), .cross("You hold the lease on the greenhouse, don't you?", "\"Yes. I'm responsible for it. I know I should have checked more often.\""), .cross("There were 64 plants, weren't there?", "\"That's what they say. I wasn't in there daily. I didn't notice them.\""), .cross("You can't prove there was a tenant, can you?", "\"I know who it was but I don't have a written agreement. I know how weak that sounds.\""), .cross("Sixty-four plants take weeks to grow. How could you miss them?", "\"The tenant kept to the far end behind a plastic curtain. I did not go back there, and I know I should have.\""), .cross("There are grow lights and fans in there. Who paid for those?", "\"Some were mine for the tomatoes. The rest came with the tenant, and I do not know who bought them.\"")],
        openings: ("Deputies found 64 marijuana plants in a greenhouse behind a hardware store. {D} leases the greenhouse, and a lab confirmed the plants. The State will show the plants, the lease, and the lab report.", "The defense will present a tomato grower who leased a greenhouse, a tenant who used part of it, and a hardware clerk who saw nothing but tomatoes."),
        closings: ("Sixty-four marijuana plants inside a greenhouse that {D} leases and controls. A leaseholder is responsible for what grows on the property, and that is {D}.", "{D} grew tomatoes and let a tenant use part of the space. The State has not proved {D} knew about or grew a single marijuana plant."),
        timeline: [(-30, "The tenant arrives."), (0, "10 a.m.: deputies."), (0, "11 a.m.: plants counted."), (0, "Noon: arrest.")],
        identified: "A search.",
        mood: .divided,
        doctrines: ["searchSeizure"])

    static let poolHallScales = SmallCases.make(
