        category: .drugs,
        headlines: ["Cooler of Cocaine Found at Boat Ramp", "K-9 Alerts on Fishing Trailer"],
        law: "traffickingCocaine",
        threshold: 8,
        spec: "Trafficked in cocaine by possession of 28 grams or more, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A K-9 alerted on a fishing trailer at a boat ramp on {DATE}. A cooler held 600 grams of cocaine. {D} owns the trailer. {DL} says {D.he} left it for a friend to use.",
        state: [E(.forensic, 3, "Lab Report", "600 grams of cocaine."), E(.physical, 3, "Cooler", "Cocaine in a false bottom.", .search), E(.document, 2, "Trailer Title", "Titled to {D}.")],
        defense: [E(.statement, 1, "Friend", "{DL} says a friend used it.")],
        role: "Deputy",
        exam: [.direct("What happened at the boat ramp on {DATE}?", "\"A K-9 alerted on a fishing trailer. Inside a cooler we found 600 grams of cocaine hidden in a false bottom.\""), .direct("Who owns the trailer?", "\"{D}. The title shows the trailer is titled to {D}. That's how we tied the cooler to {D}.\""), .direct("What did the lab say?", "\"The lab report confirmed 600 grams of cocaine. That's a distribution quantity, not a personal amount.\""), .direct("Where was the trailer parked, and what led to the alert?", "\"At a public boat ramp at dawn, hitched to nothing. We were working a tip and walked a K-9 along the lot at about 6:30.\""), .direct("Where exactly was the cocaine hidden?", "\"Inside a large cooler with a false bottom. A panel lifted out, and beneath it were bricks wrapped in tape.\""), .direct("How did you identify the owner?", "\"The trailer plate and title came back to {D}. We went to {D}'s home and spoke with {D} about it.\""), .cross("{DL} says {D.he} left the trailer for a friend to use, doesn't {D.he}?", "\"A friend has confirmed using the trailer. I can't say who put the cooler in.\""), .cross("Was {DL} at the ramp when the K-9 alerted?", "\"No. The trailer was parked there. {D} wasn't present at the time.\""), .cross("Did you find {DL}'s fingerprints on the cooler?", "\"I don't have print results to give you. I'm not going to claim something I don't have.\""), .cross("How do you know who put the cooler in the trailer?", "\"I do not. The trailer was unattended, so anyone with access could have put it there.\""), .cross("Were there fishing supplies in the trailer?", "\"Yes. Rods, tackle boxes, and a few life jackets, consistent with a fishing trip.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Did you use {DL}'s trailer?", "\"Yes. {D} said I could take it for a fishing trip. I used it for a day or two.\""), .direct("Did you bring a cooler?", "\"I brought some gear. I had coolers with fishing supplies.\""), .direct("Did {DL} know what you brought?", "\"No. {D} wasn't there. I didn't tell {D} what I had.\""), .direct("How long have you known {D}?", "\"About ten years. We fish together and swap gear. I borrowed the trailer for a trip that week.\""), .direct("What did you bring on the trip?", "\"Rods, a couple of tackle boxes, and a cooler for drinks. I loaded it the night before.\""), .direct("Where did you leave the trailer?", "\"At the ramp. I planned to come back after a short run to the store, and then I got called away.\""), .cross("Was the cooler with the false bottom yours?", "\"Not mine. I won't say whose it was. I only know it wasn't mine.\""), .cross("Did you put cocaine in any cooler?", "\"I'm not going to say anything that would incriminate me. I used the trailer, and that's all I'll say.\""), .cross("Did you leave the trailer at the ramp?", "\"Yes. I left it there. I didn't think it would be a problem.\""), .cross("Whose cooler had the false bottom?", "\"I would rather not say. I am trying to be careful about what I admit.\""), .cross("Did {D} know what you carried?", "\"No. {D} was not there when I loaded. I never told {D} what I had.\"")],
        theory: ("{D} trafficked cocaine.", "A friend."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had texted a number about a delivery.", "The friend's name is in {DL}'s phone."),
        defendant: [.direct("Why was your trailer at the ramp?", "\"I left it there for a friend to use. I let friends use my trailer for fishing trips often.\""), .direct("Whose cooler was it?", "\"Not mine. I didn't know about any false bottom. I don't own a cooler like that.\""), .direct("Did you know about the cocaine?", "\"No. If I had known, I'd never have left the trailer. I had no idea what was in it.\""), .direct("How do you use the trailer?", "\"For fishing trips and hauling gear. I let friends borrow it when I am not using it, since it sits most weekends.\""), .direct("Who borrowed it that week?", "\"A friend I trust. I texted the friend that the trailer was at the ramp and the keys were in the usual place.\""), .direct("What did you say to deputies?", "\"That I owned the trailer and had lent it. I gave them the friend's name and number and said I knew nothing about the cooler.\""), .cross("The trailer is titled to you, isn't it?", "\"Yes. I'm responsible for it. I should have been more careful about who used it.\""), .cross("600 grams is a lot of cocaine, isn't it?", "\"It is. I'm stunned. I have never had anything like that.\""), .cross("You can't prove your friend used it, can you?", "\"My friend says so. I realize a friend's word may not be enough.\""), .cross("You left a trailer unattended at a boat ramp. Isn't that careless?", "\"It is a public ramp, and I have done it before. I did not think someone would hide anything in it.\""), .cross("You texted a number about a delivery before this. What was that?", "\"It was a different matter and had nothing to do with that trailer. I do not want to guess about it here.\"")],
        openings: ("A K-9 alerted on a fishing trailer at a boat ramp, and a cooler with a false bottom held 600 grams of cocaine. The trailer is titled to {D}. The State will show the cooler, the lab report, and the title.", "The defense will point you to a trailer lent to a friend, a cooler that was not {D}'s, and an owner who was not at the ramp."),
        closings: ("Six hundred grams of cocaine in a false-bottom cooler on a trailer titled to {D}. An owner is responsible for what is in {D.his} trailer.", "{D} lent the trailer to a friend and was not at the ramp. The State has not proved {D} knew about or possessed the cocaine."),
        timeline: [(0, "Dawn: the ramp."), (0, "6:30 a.m.: K-9 alert."), (0, "7 a.m.: search."), (0, "8 a.m.: arrest.")],
        identified: "A K-9 and a search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let bathSaltsPorch = SmallCases.make(
        key: "story.bathSaltsPorch",
        category: .drugs,
        headlines: ["Man Sells Bath Salts to Neighbors From Porch", "Undercover Buy Recorded"],
        law: "saleSchedII",
        threshold: 7,
        spec: "Sold a Schedule I controlled substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "An undercover deputy bought a synthetic cathinone from {D}'s porch on {DATE}. Video recorded the exchange. {DL} says {D.he} thought they were real bath salts.",
        state: [E(.video, 3, "Buy Video", "{D} hands a bag for $40."), E(.forensic, 3, "Lab Report", "Synthetic cathinone."), E(.document, 2, "Buy Money", "Marked bills recovered.")],
        defense: [E(.statement, 1, "Bath Salts", "{DL} says {D.he} thought it was bath salts.")],
        role: "Undercover deputy",
        exam: [.direct("What did you buy from {DL}'s porch on {DATE}?", "\"I bought a bag for $40 while working undercover. The exchange was recorded on video.\""), .direct("What did the lab find?", "\"Synthetic cathinone in the bag. That is a controlled substance, not ordinary bath salts.\""), .direct("What did you do with the buy money?", "\"The marked bills were recovered afterward. They were used for the buy, and they tie the cash to {D}.\""), .direct("How did you arrange the buy?", "\"After neighbors complained about traffic at the house, I went undercover, knocked on the porch, and asked if {D} had anything for a party.\""), .direct("What happened on the porch?", "\"{D} reached into a coat pocket, handed me a small bag, and I gave $40 in marked bills. The whole exchange took about a minute.\""), .direct("How was the bag tested?", "\"A field test at 4:10 indicated a cathinone compound, and the lab later confirmed synthetic cathinone. {D} was arrested soon after.\""), .cross("{DL} says {D.he} thought they were real bath salts, doesn't {D.he}?", "\"The bag may have been labeled as bath salts. I can't say what {D} knew about the contents.\""), .cross("Did you tell {DL} what you planned to do with it?", "\"I said I wanted to get high. I'm not going to claim {D} said anything about the contents.\""), .cross("Did {DL} act like a dealer?", "\"{D} handed the bag over casually. It was a quick exchange. I didn't see a large operation.\""), .cross("Did {D} describe the product as a drug?", "\"{D} called it a party thing and did not name it. I cannot say what {D} believed it was.\""), .cross("Was the packaging labeled bath salts?", "\"Yes, the bag carried a bath-salt label with a brand name. It had no warning about ingestion.\"")],
        defenseRole: "Supplier clerk",
        defenseExam: [.direct("Do you supply products to {DL}?", "\"Yes. I work at a supplier. {D} bought bags from us that were labeled bath salts.\""), .direct("What did the label say?", "\"Bath salts. That's what the packaging said. It was a normal-looking package.\""), .direct("Was there a warning?", "\"No. I don't recall a warning on that package. We just sold it as labeled.\""), .direct("What do you do for the supplier?", "\"I work the counter and pack orders. We sell cleaning products, bath products, and novelty items.\""), .direct("How was the product marketed to you?", "\"As bath salts in small bags, with a brand and a barcode. Nothing on the label hinted at a drug.\""), .direct("How many bags did {D} buy from us?", "\"A few cases over several weeks. {D} paid by card each time.\""), .cross("Is that product safe to ingest?", "\"No. Bath salts are for the bath. They aren't meant to be ingested.\""), .cross("Did you know it contained cathinone?", "\"I didn't. I'd have said something if I did. I trusted the label.\""), .cross("Did you sell it to people who wanted to get high?", "\"I can't say what customers do with it. I sell what's on the shelf.\""), .cross("Did you ever warn buyers not to ingest the product?", "\"The bag said not for human consumption in tiny print. We did not say it out loud.\""), .cross("Did you suspect that customers used it as a drug?", "\"Some did, I suppose. I do not control what customers do after they leave.\"")],
        theory: ("{D} sold a drug.", "Bath salts."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} sold four bags that week.", "The supplier labeled the bags bath salts with no warning."),
        defendant: [.direct("What did you sell the deputy?", "\"A bag of what I thought was bath salts. The bag was labeled that way, and I sold it for $40.\""), .direct("Did you know it was synthetic cathinone?", "\"No. I thought it was a regular bath product. I didn't know what it was or that it was illegal.\""), .direct("Where did you get the bags?", "\"From a supplier. They were labeled as bath salts and sold to me that way. I had no reason to doubt it.\""), .direct("How did you come to sell these bags?", "\"A supplier offered them as novelty bath salts and gave me a price. I sold a few to people who asked for them.\""), .direct("How many bags did you sell that week?", "\"About four. I sold to people I knew from the neighborhood and did not think much about it.\""), .direct("What did the deputy say to you during the buy?", "\"Something about wanting to have a good time. I did not think the person meant to take it as a drug.\""), .cross("The buyer said it was to get high, didn't it?", "\"The buyer said something like that. I thought it was a joke. I figured it was a bath product.\""), .cross("You took $40 for it, didn't you?", "\"Yes. It was an ordinary sale. I wasn't thinking about the law.\""), .cross("The lab says it's a controlled substance, doesn't it?", "\"That's what they say. I'm shocked. I never knew.\""), .cross("The deputy said they wanted to get high. Why did you sell anyway?", "\"I thought it was a joke and that the person would use it in the bath. I should have asked more.\""), .cross("You knew people used these products for more than the bath, didn't you?", "\"I had heard something like that, but the label said bath salts. I did not research it.\"")],
        openings: ("An undercover deputy bought a bag from {D}'s porch for $40, and a lab found synthetic cathinone. Video recorded the exchange and marked bills were recovered. The State will show the video and the lab report.", "The defense will present a seller who bought bags labeled bath salts from a supplier, believed that label, and sold them openly on a porch."),
        closings: ("A $40 sale on video, a controlled substance in the bag, and the marked buy money recovered. {D} sold it and handled the cash.", "The bag said bath salts and the supplier's clerk confirms it. The State has not proved {D} knew the bag held a controlled substance."),
        timeline: [(-3, "Complaints."), (0, "4 p.m.: the buy."), (0, "4:10 p.m.: lab field test."), (1, "Arrest.")],
        identified: "A buy video.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact", "entrapment"],
        genders: ["D": .male])

    static let twoOverdoseDealer = SmallCases.make(
        key: "story.twoOverdoseDealer",
