        threshold: 8,
        spec: "Unlawfully sold a controlled substance that caused the death of {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} and another man died on {DATE} from pills in the same batch. Messages tied the sale to {D}. {DL} says the pills were bought by {V} from someone else.",
        state: [E(.digital, 3, "Messages", "{D} arranges a sale to {V}."), E(.forensic, 3, "Toxicology", "Fentanyl."), E(.document, 2, "Pill Match", "Pills match a seizure from {D}.")],
        defense: [E(.statement, 1, "Someone Else", "{DL} says {V} had another supplier.")],
        role: "Overdose investigator",
        exam: [.direct("What caused the two deaths?", "\"Fentanyl in pills from the same batch. {V} and another person died on the same day.\""), .direct("How did you trace the pills to {D}?", "\"Messages show {D} arranging a sale to {V}. Also, the pills match a seizure from {D}.\""), .direct("What did the toxicology show?", "\"Fentanyl at lethal levels in both people. The pills carried the same mark.\""), .direct("How were the two deaths discovered?", "\"Calls came in on a Sunday morning. Two people in different homes were found unresponsive within a few hours of each other. Both had pills on the table.\""), .direct("What did the pills have in common?", "\"The same stamp on the face and the same color and shape. The lab found fentanyl in each and confirmed they were from one batch.\""), .direct("What did the messages say?", "\"Messages on {V}'s phone show {D} agreeing to meet and sell pills at a price. They are dated a few days before the deaths.\""), .cross("{D} says {V} got them from someone else, doesn't {D.he}?", "\"Yes. {D} says {V} bought the pills from another source.\""), .cross("Were the messages recent?", "\"Some were old. The sale messages were from earlier days.\""), .cross("Was another dealer arrested?", "\"Yes. Another dealer was arrested with the same mark on pills. That is part of why this is hard.\""), .cross("Do the messages mention the date of the sale?", "\"They set up a meeting, but I cannot match them to the exact pills that killed {V}.\""), .cross("Was another dealer connected to the same stamp?", "\"Yes. Another dealer was arrested with pills carrying the same stamp, so it is not unique to {D}.\"")],
        defenseRole: "Friend of {V}",
        defenseExam: [.direct("Did {V} have another source for pills besides {D}?", "\"Maybe. {V} mentioned other people from time to time, though {V} never told me any names.\""), .direct("Who might the other source have been?", "\"I do not know. {V} did not tell me, and I only heard in passing that there were others.\""), .direct("How often did {V} use pills?", "\"Sometimes, whatever was available. {V} was not a regular user, as far as I could tell, but it happened.\""), .direct("How well did you know {V}?", "\"We were close friends for years. We talked almost every day, and I knew who {V} dealt with.\""), .direct("What did {V} say about where pills came from?", "\"{V} mentioned another person who would deliver and give a better price. I do not know the name.\""), .direct("What was {V} like in the days before?", "\"Stressed and low. {V} had been looking for pills for a while and was not picky about the source.\""), .cross("Did {V} ever mention {D} as a source?", "\"Yes. {V} said {D} could get pills. I do not know more than that, and I never saw a sale.\""), .cross("Did you personally see {V} buy anything from {D}?", "\"No. I did not see a sale between them. I only know what {V} told me.\""), .cross("Did you take any of the pills from that batch yourself?", "\"No, I did not. I was not there that night, and I would not have taken them.\""), .cross("Did you see {V} meet {D}?", "\"No. I never saw them together, so I cannot say whether a sale happened that week.\""), .cross("Did {V} ever say {D} was a source?", "\"Yes, earlier. {V} said {D} could get pills. After that, I heard nothing more about {D}.\"")],
        theory: ("{D} sold a fatal batch.", "Another supplier."),
        allocution: "\"I'm so sorry.\"",
        truths: ("{DL} had pills pressed with the same mark.", "Another dealer was arrested with the same mark."),
        defendant: [.direct("Did you sell pills to {V}?", "\"I sold to {V} earlier, on other days. I did not sell the batch that killed {V.him}.\""), .direct("Were those pills from your supply?", "\"No, not that batch. {V} bought them from someone else, and I do not know who that was.\""), .direct("What about the mark on the pills?", "\"It is a common mark. Many pills in town carry the same mark, and plenty of dealers have them.\""), .direct("What was your history with {V}?", "\"I knew {V} from the neighborhood and sold pills to {V} a few times. We chatted and sometimes hung out.\""), .direct("Did you sell to {V} that week?", "\"No. The messages refer to earlier days. By the weekend I had nothing to sell.\""), .direct("How did you learn about the deaths?", "\"From a friend who texted me. I was stunned. I said I was sorry and asked if anyone needed anything.\""), .cross("The messages show you arranging a sale to {V}, don't they?", "\"They are old messages. They were about other days, not about the night that {V} died.\""), .cross("Pills seized from you carry the same mark, don't they?", "\"They have the same mark. But it is a common mark, and that does not prove they came from me.\""), .cross("Two people are dead. Do you feel any responsibility?", "\"I feel terrible about it. But I did not sell that batch, and I will not say I did.\""), .cross("Pills seized from you bear the same stamp. Isn't that damning?", "\"They bear a common stamp. Lots of dealers use it, and one was arrested with the same pills.\""), .cross("Two people are dead. Aren't you at least partly responsible?", "\"I feel awful about it. I will not pretend I did nothing wrong in the past, but I did not sell that batch.\"")],
        openings: ("{V} and another person died from fentanyl pills from the same batch. Messages tie a sale to {D}, and the pills match a seizure from {D}.", "The defense evidence will establish that {V} bought the batch from someone else, that the mark on the pills is common, and that another dealer was arrested with it."),
        closings: ("Two deaths, the same batch, messages tying a sale to {D}, and pills that match a seizure from {D}. The evidence leads to {D}.", "A common mark, an old set of messages, and another dealer arrested with the same pills. The State must prove that {D} sold that batch."),
        timeline: [(-1, "The sale."), (0, "The weekend."), (0, "Overdose calls."), (2, "{DL} is arrested.")],
