        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "My son was twenty-one.",
        doctrines: ["burdenOfProof"])

    static let alteredScripts = SmallCases.make(
        key: "story.alteredScripts",
        category: .whiteCollar,
        headlines: ["Woman Altered Prescription Quantities at Several Pharmacies", "Pharmacists Compare Ink"],
        law: "prescriptionFraud",
        threshold: 7,
        spec: "Obtained controlled substances by forging and altering prescriptions, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} raised quantities on prescriptions from 10 to 40 at four pharmacies in a month. Ink and handwriting matched. {DL} says the doctor wrote the changes.",
        state: [E(.document, 3, "Altered Scripts", "Raised quantities."), E(.forensic, 3, "Handwriting Report", "Matches {D}."), E(.statement, 2, "Pharmacist", "'The 4 was added.'")],
        defense: [E(.statement, 1, "Doctor", "{DL} says the doctor wrote the changes.")],
        role: "Pharmacist",
        exam: [.direct("What did you see on the prescriptions?", "\"Quantities raised from 10 to 40 on prescriptions presented at four pharmacies in a month. The 4 had been added.\""), .direct("What did the handwriting report find?", "\"The ink and handwriting match {D}. That's what the report concluded.\""), .direct("Why was that suspicious to you?", "\"The 4 looked added in a different hand and ink. The doctor's usual prescriptions didn't look like that.\""), .direct("What first caught your eye about the prescription?", "\"The quantity read 40, but the 4 was squeezed in front of a zero in a different pen. The rest of the script was in the doctor's usual cursive.\""), .direct("What did you do?", "\"I called the doctor's office on the number printed on the form. A staff member said they had no record of a change, and I held the script and called deputies.\""), .direct("How did the other pharmacies get involved?", "\"A pharmacist at another store called me after seeing a similar script. Within a few days, four pharmacies compared notes and each had one with a raised quantity.\""), .cross("{DL} says the doctor wrote the changes, doesn't {D.he}?", "\"I never spoke to the doctor about that. I only checked the paper.\""), .cross("Could a doctor change a script after writing it?", "\"Yes, a doctor can, and usually calls us. This one did not.\""), .cross("Did {DL} act oddly at the counter?", "\"No. {D} was polite and ordinary. {D} presented the script like anyone.\""), .cross("Did you speak with the doctor directly?", "\"No. I only reached the office. The doctor was away, so I cannot tell you what the doctor intended.\""), .cross("What drug was involved?", "\"An opioid pain medication that is tightly controlled. That is why a quantity change would normally require a call from the doctor.\"")],
        defenseRole: "Doctor's assistant",
        defenseExam: [.direct("Do you work for the doctor?", "\"Yes. I'm the doctor's assistant. I handle the scripts and the schedule.\""), .direct("Did the doctor change anything?", "\"Not that I saw. I would have noticed a change to a script I prepared.\""), .direct("Was the doctor in the office that week?", "\"No. The doctor was on vacation that week. That's the week these scripts were filled.\""), .direct("What does the doctor's assistant do?", "\"I schedule patients, prepare prescriptions for the doctor's signature, and hand them to patients at the desk.\""), .direct("How does the doctor change a quantity?", "\"By writing a new prescription or calling the pharmacy. We keep a log of every change and none exists for these.\""), .direct("Where was the doctor that week?", "\"On vacation out of state. The office was covered by a locum doctor and I handled the front desk.\""), .cross("Could the doctor have changed scripts earlier?", "\"Possibly, before leaving. But I didn't see it, and I'd expect a note in the chart.\""), .cross("Did you check the chart?", "\"I did. I saw nothing about raising the quantity. That's why I'm confident.\""), .cross("Did you speak to {DL}?", "\"Only briefly. I can't say what {D} understood.\""), .cross("Did you give these scripts to {D}?", "\"I handled the pickup. I would have to check the log, but I believe {D} picked them up in person.\""), .cross("Could the doctor have changed a script before leaving?", "\"It is possible. But I see no entry in our log, and I would normally have heard about it.\"")],
        theory: ("{D} altered prescriptions.", "A doctor's change."),
        allocution: "\"I'm sorry.\"",
